function hasOnlyTcgBattlePokemonPower(card: TcgBattleCardState) {
  const isPokemonPower = (type: string) => ['pokepower', 'pokemonpower'].includes(type.replace(/[^a-z]/g, ''))
  return Boolean(card.abilities?.length && card.abilities.every((ability) => isPokemonPower((ability.type || '').toLowerCase().replace(/[^a-z]/g, ''))))
}

function hasTcgBattleUnownGiveBench(side: TcgBattleState['player']) {
  return ['g', 'i', 'v', 'e'].every((letter) => side.back.some((card) =>
    card.currentHp > 0 && card.name.replace(/[’]/g, "'").toLowerCase().normalize('NFD').replace(/\p{Diacritic}/gu, '').replace(/[^a-z0-9]/g, '') === `unown${letter}`,
  ))
}

function useTcgBattleUnownHelp(side: TcgBattleState['player']) {
  const redrawCount = side.hand.length
  side.deck.push(...side.hand.map(toTcgBattleCardSummary))
  side.hand = []
  shuffleTcgBattleDeck(side)
  const drawn = side.deck.splice(0, Math.min(redrawCount, side.deck.length))
  side.hand = drawn.map((card, index) => createTcgBattleCardState(card, index))
  return { shuffledCount: redrawCount, drawnCount: side.hand.length }
}

function hasTcgBattleUnownHelpBench(side: TcgBattleState['player']) {
  return ['h', 'e', 'l', 'p'].every((letter) => side.back.some((card) =>
    card.currentHp > 0 && card.name.replace(/[’]/g, "'").toLowerCase().normalize('NFD').replace(/\p{Diacritic}/gu, '').replace(/[^a-z0-9]/g, '') === `unown${letter}`,
  ))
}

function hasTcgBattleUnownHealBench(side: TcgBattleState['player']) {
  return ['h', 'e', 'a', 'l'].every((letter) => side.back.some((card) => card.currentHp > 0 && card.name.replace(/[’]/g, "'").toLowerCase().normalize('NFD').replace(/\p{Diacritic}/gu, '').replace(/[^a-z0-9]/g, '') === `unown${letter}`))
}

function applyTcgBattleUnownQuicken(side: TcgBattleState['player']) {
  const protectedCards = [...side.front, ...side.back].filter((card) => card.currentHp > 0 && /unown/i.test(card.name))
  for (const card of protectedCards) {
    card.incomingAttackModifier = { kind: 'preventAllEffects', remainingOpponentTurns: 1 }
  }
  return protectedCards.map((card) => card.name)
}

function applyTcgBattleToxicSludge(state: TcgBattleState) {
  for (const providerSide of ['player', 'opponent'] as const) {
    const targetSide = providerSide === 'player' ? 'opponent' : 'player'
    for (const provider of [...state[providerSide].front, ...state[providerSide].back]) {
      if (provider.currentHp <= 0 || isTcgBattleAbilitySuppressedByShadyTail(provider, [state.player, state.opponent])) continue
      const ability = provider.abilities?.find((entry) => normalizeTcgBattleAbilityCardName(provider.name) === 'muk' &&
        entry.text.replace(/[’]/g, "'").toLowerCase().normalize('NFD').replace(/\p{Diacritic}/gu, '').replace(/pokémon/g, 'pokemon').replace(/\s+/g, ' ').trim() === "at the end of each player's turn, each of your opponent's active pokemon that has any grass energy attached to it is now poisoned. if that pokemon is already poisoned, toxic sludge poke-body does nothing to that pokemon.")
      if (!ability || state[targetSide].energy <= 0 || state[targetSide].selectedEnergy?.toLowerCase() !== 'grass') continue
      for (const target of state[targetSide].front.filter((card) => card.currentHp > 0 && !card.statusConditions?.includes('poisoned'))) {
        const statusEvents = applyTcgBattleStatusConditions(state, providerSide, provider.instanceId, target.instanceId, [{ target: 'opponent', statuses: ['poisoned'] }], true)
        if (statusEvents.length > 0) state.log.unshift(`${provider.name}'s ${ability.name} Poisoned ${target.name} between turns.`)
      }
    }
  }
}

function applyEndOfRoundStatusDamage(state: TcgBattleState) {
  applyTcgBattleToxicSludge(state)
  for (const sideKey of ['player', 'opponent'] as const) {
    for (const card of state[sideKey].front.filter(
      (frontCard) => frontCard.currentHp > 0,
    )) {
      const statusesBeforeImmunity = card.statusConditions || []
      card.statusConditions = statusesBeforeImmunity.filter((status) => {
        const eligibleRecovery = isTcgBattleStatusBlockedByAbility(
          card,
          status,
          undefined,
          state,
          sideKey,
          /recover from all special conditions|remove (?:all|any) special conditions|if those pokemon are already .* remove that special condition|if any of those pokemon are .* remove that special condition/,
        )
        return !eligibleRecovery
      })
      if (!card.statusConditions.includes('poisoned') && card.temporaryEffects) {
        delete card.temporaryEffects.poisonCheckupBonus
        delete card.temporaryEffects.poisonCheckupBonusTurns
      }
      if (!card.statusConditions.includes('burned') && card.temporaryEffects) delete card.temporaryEffects.burnCheckupBonus
      if (card.statusConditions.length < statusesBeforeImmunity.length) {
        state.log.unshift(`${card.name} recovered from a Special Condition due to an Ability.`)
      }
      const statuses = card.statusConditions || []
      const poisonBonus = statuses.includes('poisoned')
        ? getTcgBattleStatusCheckupDamageBonus(state, sideKey, card, 'poisoned')
        : 0
      const burnBonus = statuses.includes('burned')
        ? getTcgBattleStatusCheckupDamageBonus(state, sideKey, card, 'burned')
        : 0
      const damage = (statuses.includes('poisoned') ? 10 : 0) + poisonBonus +
        (statuses.includes('burned') ? 10 : 0) + burnBonus
      if (damage <= 0) continue

      card.currentHp = Math.max(0, card.currentHp - damage)
      if (card.temporaryEffects?.poisonCheckupBonusTurns) {
        delete card.temporaryEffects.poisonCheckupBonus
        delete card.temporaryEffects.poisonCheckupBonusTurns
      }
      recordDamageEvent(state, {
        sourceId: card.instanceId,
        targetId: card.instanceId,
        targetSide: sideKey,
        damage,
        reason: 'status',
      })
      state.log.unshift(`${card.name} took ${damage} poison/burn damage.`)
      if (statuses.includes('burned') && card.currentHp > 0) {
        const opposingSideKey = sideKey === 'player' ? 'opponent' : 'player'
        const overheaterText = "whenever your opponent flips a coin for their burned pokemon during pokemon checkup, it doesn't recover from that special condition even if the result is heads."
        const overheater = [...state[opposingSideKey].front, ...state[opposingSideKey].back].find((provider) =>
          provider.currentHp > 0 &&
          !isTcgBattleAbilitySuppressed(provider, [state.player, state.opponent]) &&
          (provider.abilities || []).some((ability) => ability.text.replace(/[’]/g, "'").toLowerCase().normalize('NFD').replace(/\p{Diacritic}/gu, '').replace(/pokémon/g, 'pokemon').replace(/\s+/g, ' ').trim() === overheaterText),
        )
        const heatranBurnLockText = "your opponent can't remove the special condition burned by evolving or devolving his or her burned pokemon. (this also includes putting a pokemon level-up card onto the burned pokemon.) whenever your opponent flips a coin for the special condition burned between turns, treat it as tails."
        const heatranBurnLock = [...state[opposingSideKey].front, ...state[opposingSideKey].back].find((provider) =>
          provider.currentHp > 0 && normalizeTcgBattleAbilityCardName(provider.name).replace(/[^a-z0-9]/g, '') === 'heatranlvx' &&
          !isTcgBattleAbilitySuppressedByShadyTail(provider, [state.player, state.opponent]) &&
          (provider.abilities || []).some((ability) => ability.text.replace(/[’]/g, "'").toLowerCase().normalize('NFD').replace(/\p{Diacritic}/gu, '').replace(/pokémon/g, 'pokemon').replace(/\s+/g, ' ').trim() === heatranBurnLockText),
        )
        const result = heatranBurnLock ? 'tails' : flipTcgBattleCoinForSide(state, state.activeSide)
        recordCoinFlipEvent(state, { sourceId: card.instanceId, side: sideKey, results: [result], heads: result === 'heads' ? 1 : 0, tails: result === 'tails' ? 1 : 0, purpose: 'status-check' })
        if (result === 'heads' && !overheater && !heatranBurnLock) {
          card.statusConditions = card.statusConditions.filter((status) => status !== 'burned')
          if (card.temporaryEffects) delete card.temporaryEffects.burnCheckupBonus
          state.log.unshift(`${card.name} recovered from Burn after flipping heads during Pokémon Checkup.`)
        } else {
          state.log.unshift(heatranBurnLock ? `${card.name} stayed Burned because of ${heatranBurnLock.name}'s Ability treating Burn recovery flips as tails.` : overheater && result === 'heads' ? `${card.name} stayed Burned because of ${overheater.name}'s Overheater.` : `${card.name} stayed Burned after flipping tails during Pokémon Checkup.`)
        }
      }
    }
  }
  applyEndOfRoundAbilityDamage(state)
  clearSourceLinkedControlsForInactiveSources(state)
}

function applyWishiwashiTidalWaveAtOpponentTurnEnd(state: TcgBattleState, ownerSideKey: TcgBattleSide) {
  const owner = state[ownerSideKey]
  for (const source of [...owner.front, ...owner.back]) {
    if (source.currentHp <= 0 || source.currentHp >= source.hp || normalizeTcgBattleAbilityCardName(source.name) !== 'wishiwashi' || isTcgBattleAbilitySuppressedByShadyTail(source, [state.player, state.opponent])) continue
    const ability = source.abilities?.find((candidate) => candidate.text.replace(/[’]/g, "'").toLowerCase().replace(/pokémon/g, 'pokemon').replace(/\s+/g, ' ').trim() === "at the end of your opponent's turn, if this pokemon has any damage counters on it, flip a coin. if tails, shuffle this pokemon and all cards attached to it into your deck.")
    if (!ability) continue
    const result = flipTcgBattleCoinForSide(state, state.activeSide)
    recordCoinFlipEvent(state, { sourceId: source.instanceId, side: ownerSideKey, results: [result], heads: result === 'heads' ? 1 : 0, tails: result === 'tails' ? 1 : 0, purpose: 'effect' })
    if (result === 'heads') {
      state.log.unshift(`${source.name}'s ${ability.name} flipped heads and stayed in play.`)
      continue
    }
    const frontIndex = owner.front.findIndex((card) => card.instanceId === source.instanceId)
    const benchIndex = owner.back.findIndex((card) => card.instanceId === source.instanceId)
    if (frontIndex >= 0) owner.front.splice(frontIndex, 1)
    else if (benchIndex >= 0) owner.back.splice(benchIndex, 1)
    else continue
    owner.deck.push(...(source.evolutionStack || []).map((card) => ({ ...card })), toTcgBattleCardSummary(source))
    shuffleTcgBattleDeck(owner)
    state.log.unshift(`${source.name}'s ${ability.name} flipped tails and shuffled it and its Evolution cards into the deck.`)
  }
}

function applyTcgBattleDarkGengarDeepSleep(state: TcgBattleState, sleepingSideKey: TcgBattleSide): boolean {
  const deepSleepText = "as long as any dark gengar are in play, a player flips 2 coins for each of his or her pokemon that is asleep at the end of each turn. if either of them is tails, that pokemon is still asleep. this power stops working if dark gengar is asleep, confused, or paralyzed."
  const relicanthDeepSleepText = "as long as relicanth is your active pokemon, a player flips 2 coins for each of his or her pokemon that is asleep between turns. if either coin is tails, that pokemon is still asleep."
  const misdreavusSleepText = "as long as misdreavus is your active pokemon, each player flips 2 coins for his or her pokemon that is asleep between turns. if either coin is tails, that pokemon is still asleep."
  const providers = (['player', 'opponent'] as const).flatMap((providerSide) =>
    [...state[providerSide].front, ...state[providerSide].back]
      .filter((card) => card.currentHp > 0 && !card.statusConditions?.some((status) => ['asleep', 'confused', 'paralyzed'].includes(status)) && !isTcgBattleAbilitySuppressedByShadyTail(card, [state.player, state.opponent]))
      .filter((card) => providerSide === 'player' ? state.player.front.some((active) => active.instanceId === card.instanceId) || card.name.toLowerCase() === 'dark gengar' : state.opponent.front.some((active) => active.instanceId === card.instanceId) || card.name.toLowerCase() === 'dark gengar')
      .flatMap((card) => (card.abilities || []).flatMap((ability) => {
        const text = ability.text.replace(/[’]/g, "'").toLowerCase().normalize('NFD').replace(/\p{Diacritic}/gu, '').replace(/\s+/g, ' ').trim()
        const isDarkGengarDeepSleep = card.name.toLowerCase() === 'dark gengar' && text === deepSleepText
        const isRelicanthDeepSleep = card.name.toLowerCase() === 'relicanth' && text === relicanthDeepSleepText && (providerSide === 'player' ? state.player.front : state.opponent.front).some((active) => active.instanceId === card.instanceId)
        const isMisdreavusSleep = normalizeTcgBattleAbilityCardName(card.name) === 'misdreavus' && text === misdreavusSleepText && (providerSide === 'player' ? state.player.front : state.opponent.front).some((active) => active.instanceId === card.instanceId)
        return isDarkGengarDeepSleep || isRelicanthDeepSleep || isMisdreavusSleep ? [{ card, ability, side: providerSide }] : []
      })),
  )
  if (providers.length === 0) return false

  const source = providers[0]
  for (const sleeper of [...state[sleepingSideKey].front, ...state[sleepingSideKey].back].filter((card) => card.currentHp > 0 && card.statusConditions?.includes('asleep'))) {
    const results = [0, 1].map(() => flipTcgBattleCoinForSide(state, state.activeSide))
    const heads = results.filter((result) => result === 'heads').length
    recordCoinFlipEvent(state, {
      sourceId: source.card.instanceId,
      side: source.side,
      results,
      heads,
      tails: results.length - heads,
      purpose: 'effect',
    })
    if (heads === 2) {
      sleeper.statusConditions = (sleeper.statusConditions || []).filter((status) => status !== 'asleep')
      state.log.unshift(`${sleeper.name} recovered from Asleep after ${source.card.name}'s ${source.ability.name} flipped two heads.`)
    } else {
      state.log.unshift(`${sleeper.name} stayed Asleep after ${source.card.name}'s ${source.ability.name}.`)
    }
  }
  return true
}

function applyTcgBattleSnorlaxStirAndSnooze(state: TcgBattleState, sleepingSideKey: TcgBattleSide, globalTwoCoinSleepActive = false) {
  if (globalTwoCoinSleepActive) return
  const twoCoinSleepText = 'if this pokemon is asleep, flip 2 coins instead of 1 between turns. if either of them is tails, this pokemon is still asleep.'
  const slakingSleepText = 'if this pokemon is asleep, flip 2 coins instead of 1 during pokemon checkup. if either of them is tails, this pokemon is still asleep.'
  for (const sleeper of state[sleepingSideKey].front.filter((card) => card.currentHp > 0 && card.statusConditions?.includes('asleep') &&
    !isTcgBattleAbilitySuppressedByShadyTail(card, [state.player, state.opponent]) &&
    (card.abilities || []).some((ability) => [twoCoinSleepText, slakingSleepText].includes(normalizeTcgBattleAbilityText(ability.text).replace(/\s+/g, ' ').trim())),
  )) {
    const ability = sleeper.abilities?.find((entry) => [twoCoinSleepText, slakingSleepText].includes(normalizeTcgBattleAbilityText(entry.text).replace(/\s+/g, ' ').trim()))
    if (!ability) continue
    const results = [0, 1].map(() => flipTcgBattleCoinForSide(state, state.activeSide))
    const heads = results.filter((result) => result === 'heads').length
    recordCoinFlipEvent(state, { sourceId: sleeper.instanceId, side: sleepingSideKey, results, heads, tails: results.length - heads, purpose: 'effect' })
    if (heads === 2) {
      sleeper.statusConditions = (sleeper.statusConditions || []).filter((status) => status !== 'asleep')
      state.log.unshift(`${sleeper.name}'s ${ability.name} flipped two heads and it woke up.`)
    } else {
      state.log.unshift(`${sleeper.name}'s ${ability.name} kept it Asleep after flipping at least one tails.`)
    }
  }
}

function applyEndOfRoundAbilityDamage(state: TcgBattleState) {
  for (const providerSide of ['player', 'opponent'] as const) {
    const opponentSide: TcgBattleSide = providerSide === 'player' ? 'opponent' : 'player'
    const oncePerAbility = new Set<string>()
    for (const provider of [...state[providerSide].front, ...state[providerSide].back].filter((card) => card.currentHp > 0)) {
      if (isTcgBattleAbilitySuppressedByShadyTail(provider, [state.player, state.opponent])) continue
      const providerIsActive = state[providerSide].front.some((card) => card.instanceId === provider.instanceId)
      for (const ability of provider.abilities || []) {
        const text = ability.text.replace(/[’]/g, "'").toLowerCase().normalize('NFD').replace(/\p{Diacritic}/gu, '')
        const toxicSludge = normalizeTcgBattleAbilityCardName(provider.name) === 'muk' &&
          text.replace(/\s+/g, ' ').trim() === "at the end of each player's turn, each of your opponent's active pokemon that has any grass energy attached to it is now poisoned. if that pokemon is already poisoned, toxic sludge poke-body does nothing to that pokemon."
        if (toxicSludge) continue
        const checkupDamageMatch = text.match(/during pokemon checkup, if this pokemon is in the active spot, do (\d+) damage to your opponent's active pokemon/)
        const dusknoirEnergyPing = text.replace(/\s+/g, ' ').trim() === "as long as dusknoir is your active pokemon, put 1 damage counter on each of your opponent's pokemon that has any energy attached to it between turns."
        const counterDamageAbility = /between turns|during pokemon checkup/.test(text) && /put \d+ damage count(?:er)?s? on/.test(text)
        if (!counterDamageAbility && !checkupDamageMatch) continue
        if (/poisoned pokemon|burned pokemon|more damage counter|instead of|once during your turn|during your next turn|during this turn|when you play|when you attach|whenever you attach|energy attached|stadium|pokemon tool|pokemon lv\.?x as a stadium|prize cards?|flip a coin/.test(text) && !dusknoirEnergyPing) continue
        if (/as long as .*active pokemon|if this pokemon is your active pokemon|if this pokemon is in the active spot|if .* is your active pokemon/.test(text) && !providerIsActive) continue
        if (/stops working if your other active pokemon is not a victreebel/.test(text) && state[providerSide].front.some((active) =>
          active.instanceId !== provider.instanceId && active.currentHp > 0 && normalizeTcgBattleAbilityCardName(active.name) !== 'victreebel',
        )) continue
        if (/remains asleep between turns/.test(text) && !provider.statusConditions?.includes('asleep')) continue
        if (/remains affected by any special conditions/.test(text) && !provider.statusConditions?.length) continue
        if (/stops working while .*affected by a special condition|stops working if .*asleep, confused, or paralyzed/.test(text) && provider.statusConditions?.length) continue
        if (/\bif\b/.test(text) && !/if this pokemon is your active pokemon|if this pokemon is in the active spot|if .* is your active pokemon|if this pokemon remains asleep between turns|if this pokemon remains affected by any special conditions/.test(text)) continue

        const damageMatch = text.match(/put (\d+) damage count(?:er)?s? on/)
        const damage = checkupDamageMatch
          ? Number(checkupDamageMatch[1])
          : Number(damageMatch?.[1] || 0) * 10
        if (damage <= 0) continue
        const singleStack = /can't use more than 1|cannot use more than 1|doesn't stack|does not stack/.test(text)
        if (singleStack && oncePerAbility.has(ability.name)) continue

        const targets: Array<{ side: TcgBattleSide; card: TcgBattleCardState }> = []
        if (/both yours and your opponent's|both your and your opponent's/.test(text)) {
          for (const side of ['player', 'opponent'] as const) {
            const cards = /active pokemon/.test(text) ? state[side].front : [...state[side].front, ...state[side].back]
            for (const card of cards) targets.push({ side, card })
          }
        } else if (/each of your opponent's benched|each of your opponent's benched|each of your opponent's benched basic/.test(text)) {
          for (const card of state[opponentSide].back) targets.push({ side: opponentSide, card })
        } else if (/your opponent's (?:asleep|poisoned|burned|confused|paralyzed) pokemon/.test(text)) {
          for (const card of [...state[opponentSide].front, ...state[opponentSide].back]) targets.push({ side: opponentSide, card })
        } else if (/each of your opponent's|each of your opponent pokemon|each opponent's/.test(text)) {
          const cards = /active pokemon/.test(text) ? state[opponentSide].front : [...state[opponentSide].front, ...state[opponentSide].back]
          for (const card of cards) targets.push({ side: opponentSide, card })
        } else if (/each of your pokemon|each of your active pokemon/.test(text)) {
          const cards = /each of your active pokemon/.test(text) ? state[providerSide].front : [...state[providerSide].front, ...state[providerSide].back]
          for (const card of cards) targets.push({ side: providerSide, card })
        } else if (/each pokemon that remains asleep/.test(text)) {
          for (const side of ['player', 'opponent'] as const) {
            for (const card of [...state[side].front, ...state[side].back]) targets.push({ side, card })
          }
        } else if (/each pokemon that remains poisoned/.test(text)) {
          for (const side of ['player', 'opponent'] as const) {
            for (const card of [...state[side].front, ...state[side].back]) targets.push({ side, card })
          }
        } else if (/each of the defending pokemon|each defending pokemon|the defending pokemon/.test(text)) {
          for (const card of state[opponentSide].front) targets.push({ side: opponentSide, card })
        } else if (/your opponent's active pokemon/.test(text)) {
          for (const card of state[opponentSide].front) targets.push({ side: opponentSide, card })
        } else {
          targets.push({ side: providerSide, card: provider })
        }

        const requiredTypes = ['grass', 'water', 'fire', 'lightning', 'psychic', 'fighting', 'metal', 'darkness', 'dragon', 'fairy', 'colorless']
          .filter((type) => new RegExp(`\\b${type} pokemon`).test(text) && !new RegExp(`excluding ${type} pokemon`).test(text))
        const requiredSubtype = /basic pokemon (?:between turns|during pokemon checkup)/.test(text) ? 'basic' :
          /(?:each|all).*pokemon-ex between turns/.test(text) ? 'ex' :
            /pokemon lv\.?x between turns/.test(text) ? 'lv.x' : undefined
        const statusTarget = text.match(/(?:each pokemon that remains|your opponent's) (asleep|poisoned|burned|confused|paralyzed)/)?.[1]
        const needsPokemonAbility = /has any pok[eé-]?powers|has any pok[eé-]?bodies|has an ability/.test(text)
        const excludedPokemonName = text.match(/except any ([a-z][a-z '-]+)\./)?.[1]
        const excludedType = text.match(/excluding (grass|water|fire|lightning|psychic|fighting|metal|darkness|dragon|fairy|colorless) pokemon/)?.[1]
        const excludeEx = /excluding pokemon-ex/.test(text)
        let applied = false
        for (const { side, card } of targets) {
          if (card.currentHp <= 0) continue
          if (dusknoirEnergyPing && state[side].energy <= 0) continue
          if (excludedPokemonName && card.name.toLowerCase() === excludedPokemonName) continue
          if (statusTarget && !card.statusConditions?.includes(statusTarget as TcgBattleStatusCondition)) continue
          if (requiredTypes.length > 0 && !requiredTypes.some((type) => card.types.some((cardType) => cardType.toLowerCase() === type))) continue
          if (requiredSubtype && !card.subtypes.some((subtype) => {
            const normalizedSubtype = subtype.toLowerCase().replace(/[^a-z.]/g, '')
            return requiredSubtype === 'lv.x'
              ? normalizedSubtype === 'levelup' || normalizedSubtype === 'lv.x'
              : normalizedSubtype === requiredSubtype.replace(/[^a-z.]/g, '')
          })) continue
          if (excludedType && card.types.some((cardType) => cardType.toLowerCase() === excludedType)) continue
          if (excludeEx && card.subtypes.some((subtype) => subtype.toLowerCase() === 'ex' || subtype.toLowerCase() === 'pokemon-ex')) continue
          if (needsPokemonAbility && !card.abilities?.length) continue
          card.currentHp = Math.max(0, card.currentHp - damage)
          recordDamageEvent(state, {
            sourceId: provider.instanceId,
            targetId: card.instanceId,
            targetSide: side,
            damage,
            reason: 'ability',
          })
          state.log.unshift(checkupDamageMatch
            ? `${provider.name}'s ${ability.name} dealt ${damage} damage to ${card.name} during Pokémon Checkup.`
            : `${provider.name}'s ${ability.name} placed ${damage / 10} damage counter${damage === 10 ? '' : 's'} on ${card.name}.`)
          applied = true
        }
        if (applied && singleStack) oncePerAbility.add(ability.name)
      }
    }
  }
}

function applyEndOfTurnAbilityDraw(state: Pick<TcgBattleState, 'player' | 'opponent' | 'log'>, sideKey: TcgBattleSide) {
  const side = state[sideKey]
  const drawnByAbility = new Set<string>()
  for (const provider of side.front.filter((card) => card.currentHp > 0)) {
    for (const ability of provider.abilities || []) {
      const text = ability.text.replace(/[’]/g, "'").toLowerCase().normalize('NFD').replace(/\p{Diacritic}/gu, '')
      const drawMatch = text.match(/at the end of your turn, if this pokemon (?:is in the active spot|is your active pokemon), draw (\d+|a|one) cards?/)
      if (!drawMatch || /\bmay\b/.test(text)) continue
      const usageKey = /can't use more than 1|cannot use more than 1/.test(text)
        ? `shared:${ability.name}`
        : `${provider.instanceId}:${ability.name}`
      if (drawnByAbility.has(usageKey)) continue
      const count = drawMatch[1] === 'a' || drawMatch[1] === 'one' ? 1 : Number(drawMatch[1])
      const drawn = drawTcgBattleCards(side.deck, count)
      if (drawn.length === 0) continue
      const drawnCounts = new Map<string, number>()
      for (const card of drawn) drawnCounts.set(card.id, (drawnCounts.get(card.id) || 0) + 1)
      side.deck = side.deck.filter((card) => {
        const remaining = drawnCounts.get(card.id) || 0
        if (remaining === 0) return true
        drawnCounts.set(card.id, remaining - 1)
        return false
      })
      side.hand.push(...drawn)
      drawnByAbility.add(usageKey)
      state.log.unshift(`${provider.name}'s ${ability.name} drew ${drawn.length} card${drawn.length === 1 ? '' : 's'}.`)
    }
  }
}

function applyEndOfTurnAbilityDiscard(state: Pick<TcgBattleState, 'player' | 'opponent' | 'log'>, sideKey: TcgBattleSide) {
  const side = state[sideKey]
  const opposingSide = state[sideKey === 'player' ? 'opponent' : 'player']
  for (const provider of side.front.filter((card) => card.currentHp > 0 && !isTcgBattleAbilitySuppressedByShadyTail(card, [state.player, state.opponent]))) {
    const windErosion = (provider.abilities || []).find((entry) => entry.text.replace(/[’]/g, "'").toLowerCase().normalize('NFD').replace(/\p{Diacritic}/gu, '').replace(/pokémon/g, 'pokemon').replace(/\s+/g, ' ').trim() === "as long as flygon is your active pokemon, discard the top card from your opponent's deck between turns.")
    if (normalizeTcgBattleAbilityCardName(provider.name) === 'flygonlvx' && windErosion) {
      const discarded = opposingSide.deck.shift()
      if (discarded) {
        opposingSide.discard.push(createTcgBattleCardState(discarded, opposingSide.discard.length))
        state.log.unshift(`${provider.name}'s ${windErosion.name} discarded ${discarded.name} from the opponent's deck between turns.`)
      }
    }
    const ability = (provider.abilities || []).find((entry) => entry.text.replace(/[’]/g, "'").toLowerCase().normalize('NFD').replace(/\p{Diacritic}/gu, '').replace(/pokémon/g, 'pokemon').replace(/\s+/g, ' ').trim() === 'once at the end of your turn (after your attack), if this pokemon is in the active spot, you must discard the top 5 cards of your deck.')
    if (!ability) continue
    const discarded = side.deck.splice(0, 5)
    side.discard.push(...discarded.map((card, index) => createTcgBattleCardState(card, side.discard.length + index)))
    state.log.unshift(`${provider.name}'s ${ability.name} discarded ${discarded.length} card${discarded.length === 1 ? '' : 's'} from the top of the deck.`)
  }
}

function applyEndOfTurnAbilityHealing(state: TcgBattleState, sideKey: TcgBattleSide) {
  if (isTcgBattleHealingPrevented(state)) return
  const side = state[sideKey]
  for (const provider of side.front.filter((card) => card.currentHp > 0)) {
    for (const ability of provider.abilities || []) {
      const text = ability.text.replace(/[’]/g, "'").toLowerCase().normalize('NFD').replace(/\p{Diacritic}/gu, '').replace(/\s+/g, ' ')
      const healMatch = text.match(/at the end of your turn(?: \(after your attack\))?, if this pokemon (?:is in the active spot|is your active pokemon), heal (\d+) damage from it/)
      if (!healMatch || /\bmay\b/.test(text)) continue
      const healed = Math.min(getTcgBattleAbilityHealingAmount(provider, Number(healMatch[1])), provider.hp - provider.currentHp)
      if (healed <= 0) continue
      provider.currentHp += healed
      state.log.unshift(`${provider.name} healed ${healed} damage from its ${ability.name}.`)
    }
  }
}

function getTcgBattleStatusCheckupDamageBonus(
  state: TcgBattleState,
  targetSide: TcgBattleSide,
  target: TcgBattleCardState,
  status: TcgBattleStatusCondition,
): number {
  let bonus = 0
  if (status === 'poisoned' && target.statusConditions?.includes('poisoned')) bonus += target.temporaryEffects?.poisonCheckupBonus || 0
  if (status === 'burned' && target.statusConditions?.includes('burned')) bonus += target.temporaryEffects?.burnCheckupBonus || 0
  let fieryAuraActive = false
  let opponentBurningScalesActive = false
  const singleStackAbilities = new Set<string>()
  for (const providerSide of ['player', 'opponent'] as const) {
    const side = state[providerSide]
    for (const provider of [...side.front, ...side.back].filter((card) => card.currentHp > 0)) {
      const providerIsActive = side.front.some((card) => card.instanceId === provider.instanceId)
      for (const ability of provider.abilities || []) {
        const text = ability.text.replace(/[’]/g, "'").toLowerCase().normalize('NFD').replace(/\p{Diacritic}/gu, '')
        if (
          status === 'poisoned' &&
          providerSide !== targetSide &&
          normalizeTcgBattleAbilityCardName(provider.name).replace(/[^a-z0-9]/g, '') === 'nihilego' &&
          text.replace(/\s+/g, ' ').trim() === "your opponent's active pokemon takes +10 damage from being poisoned." &&
          !isTcgBattleAbilitySuppressedByShadyTail(provider, [state.player, state.opponent])
        ) {
          bonus += 10
          continue
        }
        if (
          status === 'burned' &&
          providerSide !== targetSide &&
          normalizeTcgBattleAbilityCardName(provider.name) === 'pyroar' &&
          text.replace(/\s+/g, ' ').trim() === "during pokemon checkup, put 4 damage counters on your opponent's burned pokemon instead of 2." &&
          !isTcgBattleAbilitySuppressedByShadyTail(provider, [state.player, state.opponent])
        ) {
          bonus += 20
          continue
        }
        if (
          status === 'burned' &&
          providerSide !== targetSide &&
          normalizeTcgBattleAbilityCardName(provider.name) === 'infernape' &&
          text.replace(/\s+/g, ' ').trim() === "put 6 damage counters instead of 2 on your opponent's burned pokemon between turns." &&
          !isTcgBattleAbilitySuppressedByShadyTail(provider, [state.player, state.opponent])
        ) {
          bonus += 40
          continue
        }
        if (
          status === 'burned' &&
          providerSide !== targetSide &&
          normalizeTcgBattleAbilityCardName(provider.name).replace(/[^a-z0-9]/g, '') === 'volcarona' &&
          text.replace(/\s+/g, ' ').trim() === "put 4 damage counters instead of 2 on your opponent's burned pokemon between turns." &&
          !isTcgBattleAbilitySuppressedByShadyTail(provider, [state.player, state.opponent])
        ) {
          opponentBurningScalesActive = true
          continue
        }
        if (
          status === 'poisoned' &&
          providerIsActive &&
          normalizeTcgBattleAbilityCardName(provider.name).replace(/[^a-z0-9]/g, '') === 'darkweezing' &&
          text.replace(/\s+/g, ' ').trim() === 'as long as dark weezing is your active pokemon, put 1 damage counter on each pokemon that remains poisoned between turns.' &&
          !isTcgBattleAbilitySuppressedByShadyTail(provider, [state.player, state.opponent])
        ) {
          bonus += 10
          continue
        }
        if (
          status === 'burned' &&
          providerIsActive &&
          normalizeTcgBattleAbilityCardName(provider.name).replace(/[^a-z0-9]/g, '') === 'rapidash' &&
          text.replace(/\s+/g, ' ').trim() === 'as long as rapidash is your active pokemon, put 4 damage counters instead of 2 on burned pokemon between turns.' &&
          !isTcgBattleAbilitySuppressedByShadyTail(provider, [state.player, state.opponent])
        ) {
          fieryAuraActive = true
          continue
        }
        const match = text.match(/(?:put|puts) (\d+) more damage counters? on (?:each |your opponent's |your )?[^.]*\b(poisoned|burned)\b/)
        if (!match || match[2] !== status) continue
        if (/as long as this pokemon is in the active spot|as long as .*active pokemon/.test(text) && !providerIsActive) continue
        if (/can't be used if .*affected by a special condition|stops working while .*affected by a special condition/.test(text) && provider.statusConditions?.length) continue
        if (/non-darkness|excluding darkness/.test(text) && target.types.some((type) => type.toLowerCase() === 'darkness')) continue

        const affectsBothSides = /each player|both yours and your opponent's|each poisoned|each burned|his or her poisoned|his or her burned/.test(text)
        const affectsOpponent = /your opponent's (?:poisoned|burned)/.test(text)
        const affectsOwnSide = /your (?:poisoned|burned)/.test(text)
        if (affectsOpponent && providerSide === targetSide) continue
        if (affectsOwnSide && providerSide !== targetSide) continue
        if (!affectsBothSides && !affectsOpponent && !affectsOwnSide) continue

        const oncePerName = /can't apply more than 1|cannot apply more than 1|doesn't stack|does not stack/.test(text)
        if (oncePerName && singleStackAbilities.has(ability.name)) continue
        if (oncePerName) singleStackAbilities.add(ability.name)
        bonus += Number(match[1]) * 10
      }
    }
  }
  return bonus + (fieryAuraActive || opponentBurningScalesActive ? 30 : 0)
}

function applyEndOfRoundAbilityHealing(state: TcgBattleState) {
  for (const sideKey of ['player', 'opponent'] as const) {
    const side = state[sideKey]
    const oncePerAbility = new Set<string>()
    for (const provider of [...side.front, ...side.back].filter((card) => card.currentHp > 0)) {
      if (isTcgBattleAbilitySuppressedByShadyTail(provider, [state.player, state.opponent])) continue
      for (const ability of provider.abilities || []) {
        const text = ability.text.replace(/[’]/g, "'").toLowerCase().normalize('NFD').replace(/\p{Diacritic}/gu, '')
        const rocketSnorlaxDarkHealer = normalizeTcgBattleAbilityCardName(provider.name) === "rocket's snorlax ex" &&
          text.replace(/["']+$/g, '').trim() === "as long as rocket's snorlax ex has any darkness energy attached to it, remove 1 damage counter from rocket's snorlax ex between turns."
        const usageKey = /can't use more than 1|cannot use more than 1/.test(text)
          ? `shared:${ability.name}`
          : `${provider.instanceId}:${ability.name}`
        if (oncePerAbility.has(usageKey)) continue
        if (/stops working while .*asleep, confused, or paralyzed|can't be used if .*asleep, confused, or paralyzed/.test(text) &&
          provider.statusConditions?.some((status) => ['asleep', 'confused', 'paralyzed'].includes(status))) continue
        if (/energy attached|stadium|tool attached/.test(text) && !rocketSnorlaxDarkHealer) continue
        if (rocketSnorlaxDarkHealer && (side.energy <= 0 || side.selectedEnergy?.toLowerCase() !== 'darkness')) continue
        if (/if .* is your active pokemon|if this pokemon is in the active spot/.test(text) &&
          !side.front.some((frontCard) => frontCard.instanceId === provider.instanceId)) continue
        if (/if this pokemon remains asleep between turns|if .* remains asleep between turns/.test(text) &&
          !provider.statusConditions?.includes('asleep')) continue
        if (/if .* remains affected by any special conditions between turns/.test(text) && !provider.statusConditions?.length) continue
        const requiredName = text.match(/if you have ([a-z0-9 '’-]+) in play/)
        if (requiredName && ![...side.front, ...side.back].some((card) => normalizeTcgBattleAbilityCardName(card.name).includes(normalizeTcgBattleAbilityCardName(requiredName[1].trim())))) continue

        const betweenTurns = /between turns|during pokemon checkup/.test(text)
        const amountPattern = /(?:heal (\d+) damage from|remove (\d+) damage counters? from)/
        const healMatch = betweenTurns ? text.match(amountPattern) : null
        const healAll = betweenTurns && /heal all damage from (?:this pokemon|[a-z0-9 '’-]+)/.test(text)
        if (!healMatch && !healAll) continue

        const amount = healAll ? 0 : Number(healMatch?.[1] || healMatch?.[2]) * (healMatch?.[2] ? 10 : 1)
        const scopeStart = text.indexOf(healAll ? 'heal all damage from' : healMatch![0])
        const scopeText = text.slice(scopeStart)
        let targets: TcgBattleCardState[]
        if (/each of your (?:benched )?pokemon/.test(scopeText)) {
          targets = [...side.front, ...side.back]
          if (/each of your benched pokemon/.test(scopeText)) targets = side.back
        } else if (/each pokemon .*both yours and your opponent's/.test(scopeText)) {
          targets = [
            ...state.player.front, ...state.player.back,
            ...state.opponent.front, ...state.opponent.back,
          ]
        } else {
          const namedTarget = scopeText.match(/(?:heal (?:\d+|all) damage from|remove \d+ damage counters? from) ([a-z0-9 '’-]+?)(?: between turns|\.|\s+\()/)?.[1]
          const normalizedTargetName = normalizeTcgBattleAbilityCardName(namedTarget || '')
          targets = namedTarget && normalizedTargetName !== 'this pokemon' && normalizedTargetName !== 'this card'
            ? [...side.front, ...side.back].filter((card) => normalizeTcgBattleAbilityCardName(card.name).includes(normalizedTargetName))
            : [provider]
        }
        if (/excluding pokemon-ex/.test(scopeText)) {
          targets = targets.filter((card) => !card.subtypes.some((subtype) => subtype.toLowerCase() === 'ex'))
        }
        oncePerAbility.add(usageKey)
        for (const card of targets.filter((entry) => entry.currentHp > 0)) {
          if (/remains asleep/.test(text) && !card.statusConditions?.includes('asleep')) continue
          if (/remains affected by any special conditions/.test(text) && !card.statusConditions?.length) continue
          if (/as long as .*active pokemon/.test(text) && !side.front.some((frontCard) => frontCard.instanceId === provider.instanceId)) continue
          if (isTcgBattleHealingPrevented(state)) continue
          const healingAmount = healAll ? card.hp - card.currentHp : amount
          const healed = Math.min(getTcgBattleAbilityHealingAmount(card, healingAmount), card.hp - card.currentHp)
          if (healed <= 0) continue
          card.currentHp += healed
          state.log.unshift(`${card.name} healed ${healed} damage from ${provider.name}'s ${ability.name}.`)
        }
      }
    }
  }
}

function finishOpponentTurn(state: TcgBattleState, preserveExtraAttack = false) {
  if (!preserveExtraAttack) {
    applyWishiwashiTidalWaveAtOpponentTurnEnd(state, 'player')
    applyEndOfTurnAbilityDraw(state, 'opponent')
    applyEndOfTurnAbilityDiscard(state, 'opponent')
    applyEndOfTurnAbilityHealing(state, 'opponent')
    applyEndOfRoundStatusDamage(state)
    applyEndOfRoundAbilityHealing(state)
    const globalTwoCoinSleepActive = applyTcgBattleDarkGengarDeepSleep(state, 'opponent')
    applyTcgBattleSnorlaxStirAndSnooze(state, 'opponent', globalTwoCoinSleepActive)
  }
  promoteOpponentIfNeeded(state)
  const winner = getTcgBattleWinner(state)
  if (winner) {
    state.extraAttackPending = undefined
    state.phase = 'finished'
    state.winner = winner
    return
  }
  requirePlayerPromotionIfNeeded(state)
  if (state.pendingPromotion) return
  if (preserveExtraAttack) {
    state.activeSide = 'opponent'
    runOpponentTurn(state)
    return
  }
  state.extraAttackPending = undefined
  advanceTurn(state, 'player')
  finishByStallIfNeeded(state)
}

function applyAttack(
  state: TcgBattleState,
  sideKey: TcgBattleSide,
  attacker: TcgBattleCardState,
  attackIndex: number,
  target: TcgBattleCardState,
  choice?: TcgBattleAttackChoice,
) {
  syncTcgBattleDittoTransform(state)
  const side = state[sideKey]
  const attack = getTcgBattleAvailableAttacks(state, sideKey, attacker)[attackIndex]
  if (!attack) throw new Error('Invalid attack.')
  if (isTcgBattleSideAttackLocked(state, sideKey)) {
    throw new Error(`${attacker.name} cannot attack during this turn.`)
  }
  if (isTcgBattleAttackDisabled(attacker, attackIndex)) {
    throw new Error(`${attack.name} is disabled this turn.`)
  }
  if (!isTcgBattleAbilityAttackAllowed(state, sideKey, attacker)) {
    throw new Error(`${attacker.name} cannot attack until its Ability requirement is met.`)
  }

  const energyCost = getEffectiveTcgBattleAttackCost(state, attack, attacker, sideKey)
  if (energyCost > side.energy) throw new Error('Not enough energy.')
  if (energyCost > getAllowedTcgBattleAttackCost(state.turnNumber)) {
    throw new Error('That attack costs too much energy for this turn.')
  }
  const unlockTurn = getTcgBattleCardUnlockTurnForCard(attacker)
  if (state.turnNumber < unlockTurn) {
    throw new Error(`${attacker.name} is locked until turn ${unlockTurn}.`)
  }
  const choiceError = validateTcgBattleAttackChoice({
    state,
    sideKey,
    attacker,
    attack,
    target,
    choice,
    paidAttackCost: energyCost,
  })
  if (choiceError) throw new Error(choiceError)

  const defendingSide = sideKey === 'player' ? 'opponent' : 'player'
  const invisibleTentaclesText = "whenever your opponent's pokemon tries to attack, your opponent discards 1 card from his or her hand. (if your opponent can't discard 1 card, your opponent's pokemon can't attack.) you can't use more than 1 invisible tentacles poke-body each turn."
  const defendingBoard = [...state[defendingSide].front, ...state[defendingSide].back]
  const invisibleTentaclesUsed = defendingBoard.some((provider) => provider.abilityUses?.['shared:invisible tentacles'] === state.turnNumber)
  const invisibleTentacles = invisibleTentaclesUsed ? undefined : defendingBoard
    .filter((provider) => provider.currentHp > 0 && !isTcgBattleAbilitySuppressedByShadyTail(provider, [state.player, state.opponent]))
    .flatMap((provider) => (provider.abilities || []).map((ability, abilityIndex) => ({ provider, ability, abilityIndex })))
    .find(({ provider, ability, abilityIndex }) => normalizeTcgBattleAbilityCardName(provider.name) === 'giratinalvx' && ability.text.replace(/[’]/g, "'").toLowerCase().normalize('NFD').replace(/\p{Diacritic}/gu, '').replace(/\s+/g, ' ').trim() === invisibleTentaclesText && provider.abilityUses?.[`shared:invisible tentacles`] !== state.turnNumber && provider.abilityUses?.[`${abilityIndex}:${ability.name}`] !== state.turnNumber)
  if (invisibleTentacles) {
    if (side.hand.length === 0) throw new Error("Giratina LV.X's Invisible Tentacles prevents this attack because you have no card to discard.")
    const discardIndex = randomInt(0, side.hand.length)
    side.discard.push(...side.hand.splice(discardIndex, 1))
    invisibleTentacles.provider.abilityUses = { ...invisibleTentacles.provider.abilityUses, 'shared:invisible tentacles': state.turnNumber, [`${invisibleTentacles.abilityIndex}:${invisibleTentacles.ability.name}`]: state.turnNumber }
    state.log.unshift(`${sideKey === 'player' ? 'Player' : 'Opponent'} discarded a card to ${invisibleTentacles.provider.name}'s Invisible Tentacles.`)
  }

  const defendingSideTurnNumber = getNextTcgBattleTurnNumber(
    state.turnNumber,
    sideKey,
    defendingSide,
  )
  const damageEventStartIndex = state.lastDamageEvents?.length || 0
  const statusEventStartIndex = state.lastStatusEvents?.length || 0
  const existingDefenderTurnKnockout = state.lastOpponentAttackKnockout?.[defendingSide]
  const existingKnockoutIsSameTurn = existingDefenderTurnKnockout?.turnNumber === defendingSideTurnNumber
  state.lastOpponentAttackKnockout = {
    ...state.lastOpponentAttackKnockout,
    [defendingSide]: existingKnockoutIsSameTurn ? existingDefenderTurnKnockout : { turnNumber: defendingSideTurnNumber, knockedOut: false, knockedOutNames: [], knockedOutTypes: [], knockedOutRuleBox: false, knockedOutGrassPokemon: false },
  }
  state.lastAction = {
    id: randomUUID(),
    side: sideKey,
    kind: 'attack',
    attackerId: attacker.instanceId,
    attackIndex,
    targetId: target.instanceId,
  }
  const attackerTemporaryEffects = getTemporaryEffects(attacker)
  attackerTemporaryEffects.lastAttackTurnNumber = state.turnNumber
  const sideAttackHistory = state.attackHistoryBySide?.[sideKey] || []
  const currentTurnHistory = sideAttackHistory.find((entry) => entry.turnNumber === state.turnNumber)
  const attackHistoryEntry = {
    attackerId: attacker.instanceId,
    cardName: attacker.name,
    subtypes: [...attacker.subtypes],
    attackName: attack.name,
    attack: { ...attack, cost: [...attack.cost] },
  }
  const updatedSideAttackHistory = currentTurnHistory
    ? sideAttackHistory.map((entry) => entry.turnNumber === state.turnNumber
      ? { ...entry, attacks: [...entry.attacks, attackHistoryEntry] }
      : entry)
    : [...sideAttackHistory, { turnNumber: state.turnNumber, attacks: [attackHistoryEntry] }]
  state.attackHistoryBySide = {
    ...state.attackHistoryBySide,
    [sideKey]: updatedSideAttackHistory.slice(-2),
  }
  const onceWhilePokemonInPlay = getTcgBattleAttackEffect(attack)?.onceWhilePokemonInPlay
  if (onceWhilePokemonInPlay) {
    const requiredPokemon = normalizeTcgBattleAbilityText(onceWhilePokemonInPlay).replace(/[^a-z0-9]/g, '')
    const sourceRemainsInPlay = normalizeTcgBattleAbilityText(attacker.name).replace(/[^a-z0-9]/g, '') === requiredPokemon ||
      (attacker.evolutionStack || []).some((stage) => normalizeTcgBattleAbilityText(stage.name).replace(/[^a-z0-9]/g, '') === requiredPokemon)
    if (sourceRemainsInPlay) {
      const usedAttack = getTcgBattleAttackUsageKey(attack)
      attacker.attacksUsedWhileInPlay = [...new Set([...(attacker.attacksUsedWhileInPlay || []), usedAttack])]
    }
  }

  const statusCheck = resolveTcgBattleStatusAttackCheck(
    attacker,
    state[sideKey].temporaryCoinFlipOverride?.turnNumber === state.turnNumber ? () => 0 : Math.random,
    getTcgBattleAttackEffect(attack)?.allowWhileAsleep,
  )
  if (statusCheck.coinFlips) {
    recordCoinFlipEvent(state, {
      sourceId: attacker.instanceId,
      side: sideKey,
      results: statusCheck.coinFlips.results,
      heads: statusCheck.coinFlips.heads,
      tails: statusCheck.coinFlips.tails,
      purpose: 'status-check',
    })
  }
  if (statusCheck.clearedStatus) {
    clearTcgBattleControlStatus(attacker, statusCheck.clearedStatus)
    state.log.unshift(
      `${attacker.name} shook off ${statusCheck.clearedStatus}.`,
    )
  }
  const mistyGyaradosRebellion = attacker.name.replace(/[’]/g, "'").toLowerCase() === "misty's gyarados" &&
    !isTcgBattleAbilitySuppressedByShadyTail(attacker, [state.player, state.opponent]) &&
    (attacker.abilities || []).some((ability) => {
      const text = ability.text.replace(/[’]/g, "'").toLowerCase().normalize('NFD').replace(/\p{Diacritic}/gu, '').replace(/pokémon/g, 'pokemon').replace(/\s+/g, ' ').trim()
      return text === "whenever misty's gyarados attacks, flip 2 coins. if both of them are tails, that attack does nothing. instead, shuffle misty's gyarados and all cards attached to it into your deck. (this power works even if misty's gyarados is confused.)"
    })
  if (mistyGyaradosRebellion) {
    const results = [0, 1].map(() => flipTcgBattleCoinForSide(state, state.activeSide))
    recordCoinFlipEvent(state, {
      sourceId: attacker.instanceId,
      side: sideKey,
      results,
      heads: results.filter((result) => result === 'heads').length,
      tails: results.filter((result) => result === 'tails').length,
      purpose: 'effect',
    })
    if (results.every((result) => result === 'tails')) {
      side.energy = Math.max(0, side.energy - energyCost)
      const frontIndex = side.front.findIndex((card) => card.instanceId === attacker.instanceId)
      const backIndex = side.back.findIndex((card) => card.instanceId === attacker.instanceId)
      if (frontIndex >= 0) side.front.splice(frontIndex, 1)
      else if (backIndex >= 0) side.back.splice(backIndex, 1)
      else return
      side.deck.push(...(attacker.evolutionStack || []).map((card) => ({ ...card })), toTcgBattleCardSummary(attacker))
      shuffleTcgBattleDeck(side)
      compactTcgBattleBoard(side)
      state.consecutivePasses = 0
      state.log.unshift(`${attacker.name}'s Rebellion flipped two tails, so the attack did nothing and ${attacker.name} and its evolution cards were shuffled into its owner's deck.`)
      return
    }
  }
  if (!statusCheck.canAttack) {
    const confusionDamageBonus = statusCheck.selfDamage > 0 && attacker.statusConditions?.includes('confused') &&
      !isTcgBattleAbilitySuppressedByShadyTail(attacker, [state.player, state.opponent]) &&
      (attacker.abilities || []).some((ability) => {
        const text = ability.text.replace(/[’]/g, "'").toLowerCase().normalize('NFD').replace(/\p{Diacritic}/gu, '').replace(/pokémon/g, 'pokemon').replace(/\s+/g, ' ').trim()
        return /^if dark primeape does any damage while it's confused \(even to itself\), it does 30 more\.$/.test(text)
      }) ? 30 : 0
    const confusionDamage = statusCheck.selfDamage + confusionDamageBonus
    if (confusionDamage > 0) {
      attacker.currentHp = Math.max(
        0,
        attacker.currentHp - confusionDamage,
      )
      recordDamageEvent(state, {
        sourceId: attacker.instanceId,
        targetId: attacker.instanceId,
        targetSide: sideKey,
        damage: confusionDamage,
        reason: 'confusion',
      })
      if (attacker.currentHp <= 0) {
        compactTcgBattleBoard(side)
        if (sideKey === 'opponent') promoteOpponentIfNeeded(state)
        else requirePlayerPromotionIfNeeded(state)
      }
    }
    state.consecutivePasses = 0
    const damageSummary =
      confusionDamage > 0
        ? ` ${attacker.name} took ${confusionDamage} confusion damage.`
        : ''
    state.log.unshift(
      `${sideKey === 'player' ? 'Your' : "Opponent's"} ${attacker.name} could not attack while ${statusCheck.blockedStatus}.${damageSummary}`,
    )
    return
  }

  if (getTcgBattleAttackEffect(attack)?.oncePerGameVstar) {
    if (side.usedVstarPower) throw new Error('You have already used a VSTAR Power this game.')
    side.usedVstarPower = true
  }
  if (getTcgBattleAttackEffect(attack)?.oncePerGameGx) {
    if (side.usedGxAttack || side.gxAttacksLocked) throw new Error('A GX attack has already been used or locked this game.')
    side.usedGxAttack = true
  }

  if (attacker.temporaryEffects?.attackFailsOnTails) {
    const flippingSide = sideKey === 'player' ? 'opponent' : 'player'
    const result = flipTcgBattleCoinForSide(state, flippingSide)
    recordCoinFlipEvent(state, {
      sourceId: attacker.instanceId,
      side: flippingSide,
      results: [result],
      heads: result === 'heads' ? 1 : 0,
      tails: result === 'tails' ? 1 : 0,
      purpose: 'attack-failure',
    })
    if (result === 'tails') {
      state.consecutivePasses = 0
      state.log.unshift(`${attacker.name}'s attack did nothing after a tails flip.`)
      return
    }
  }

  const attackIgnoresTargetEffects = doesTcgBattleAttackIgnoreTargetDamageModifiers(state, sideKey, attacker, target, attack, energyCost)
  const incomingEffectsBlocked = (pokemon: TcgBattleCardState) => pokemon.incomingAttackModifier?.kind === 'preventAllEffects' &&
    (!pokemon.incomingAttackModifier.activeOnly || state[sideKey === 'player' ? 'opponent' : 'player'].front.some((card) => card.instanceId === pokemon.instanceId))
  let blockTargetEffects =
    incomingEffectsBlocked(target) ||
    isTcgBattleAttackEffectBlockedByAbility(target, attacker, state, sideKey, attack.name, attackIgnoresTargetEffects)
  const beforeDamageSwitch = getTcgBattleAttackEffect(attack)?.special?.find(
    (rule) => rule.kind === 'switch' && rule.beforeDamage,
  )
  if (
    beforeDamageSwitch?.kind === 'switch' &&
    !blockTargetEffects &&
    choice?.kind === 'benchSwitch'
  ) {
    const switchSide = beforeDamageSwitch.target === 'self' ? sideKey : sideKey === 'player' ? 'opponent' : 'player'
    const switched = swapTcgBattleCards(state, switchSide, target, choice.cardId)
    if (switched) {
      const replacement = state[switchSide].front.find((card) => card.instanceId === choice.cardId)
      if (replacement) target = replacement
    }
  }
  blockTargetEffects = incomingEffectsBlocked(target) ||
    isTcgBattleAttackEffectBlockedByAbility(target, attacker, state, sideKey, attack.name, attackIgnoresTargetEffects)
  const normalizedHaunterText = (text: string) => text.replace(/[’]/g, "'").toLowerCase().normalize('NFD').replace(/\p{Diacritic}/gu, '').replace(/pokémon/g, 'pokemon').replace(/\s+/g, ' ').trim()
  const hasTransparency = !target.statusConditions?.length &&
    !isTcgBattleAbilitySuppressedByShadyTail(target, [state.player, state.opponent]) &&
    (target.abilities || []).some((ability) => ["whenever an attack does anything to haunter, flip a coin. if heads, prevent all effects of that attack, including damage, done to haunter. this power stops working while haunter is affected by a special condition.", "whenever an attack does anything to haunter, flip a coin. if heads, prevent all effects of that attack, including damage, done to haunter. this power stops working while haunter is asleep."].includes(normalizedHaunterText(ability.text)))
  let transparencyBlocked = false
  if (hasTransparency) {
    const targetSide = [...side.front, ...side.back].some((card) => card.instanceId === target.instanceId)
      ? sideKey
      : sideKey === 'player' ? 'opponent' : 'player'
    const result = flipTcgBattleCoinForSide(state, targetSide)
    recordCoinFlipEvent(state, {
      sourceId: target.instanceId,
      side: targetSide,
      results: [result],
      heads: result === 'heads' ? 1 : 0,
      tails: result === 'tails' ? 1 : 0,
      purpose: 'effect',
    })
    transparencyBlocked = result === 'heads'
    if (transparencyBlocked) {
      blockTargetEffects = true
      state.log.unshift(`${target.name}'s Transparency flipped heads and prevented the attack's effects, including damage.`)
    }
  }
  const targetHadDestinyBond = Boolean(target.temporaryEffects?.destinyBond)
  const targetReflectDamage = target.temporaryEffects?.reflectDamage
  const resolution = resolveTcgBattleAttack({
    state,
    sideKey,
    attacker,
    attack,
    target,
    paidAttackCost: energyCost,
    choice,
  })
  if (transparencyBlocked) {
    resolution.targetDamage = 0
    resolution.benchDamage = resolution.benchDamage?.filter((hit) => hit.targetId !== target.instanceId)
    resolution.counterDamage = resolution.counterDamage?.filter((hit) => hit.targetId !== target.instanceId)
    resolution.healing = resolution.healing?.filter((hit) => hit.targetId !== target.instanceId)
    resolution.protection = resolution.protection?.filter((hit) => hit.targetId !== target.instanceId)
    resolution.statusConditions = resolution.statusConditions?.filter((effect) => effect.target !== 'opponent')
  }
  side.energy -= energyCost
  const applicableEnergyDiscards = blockTargetEffects
    ? resolution.energyDiscards?.filter((discard) => discard.target === 'self')
    : resolution.energyDiscards
  applyTcgBattleEnergyDiscards(state, sideKey, applicableEnergyDiscards)
  resolution.statusConditions = resolution.statusConditions?.filter((status) =>
    status.requiresExtraEnergy === undefined || side.energy >= status.requiresExtraEnergy,
  )
  for (const gain of resolution.energyGains || []) {
    if (
      gain.requiresSourceSurvival &&
      (resolution.selfKnockOut || attacker.currentHp - resolution.selfDamage <= 0)
    ) continue
    const targetSide =
      gain.target === 'self'
        ? sideKey
        : sideKey === 'player'
          ? 'opponent'
          : 'player'
    const before = state[targetSide].energy
    state[targetSide].energy = Math.min(
      TCG_BATTLE_FORMATS[state.format].energyCap,
      before + gain.amount,
    )
    const added = state[targetSide].energy - before
    if (added > 0) {
      recordEffectEvent(state, {
        kind: 'energy',
        side: targetSide,
        sourceId: attacker.instanceId,
        amount: added,
      })
    }
  }
  if (resolution.coinFlips) {
    recordCoinFlipEvent(state, {
      sourceId: attacker.instanceId,
      side: sideKey,
      results: resolution.coinFlips.results,
      heads: resolution.coinFlips.heads,
      tails: resolution.coinFlips.tails,
      purpose: 'attack',
    })
  }
  if (resolution.abilityCoinFlips && resolution.unownXProviderIds?.length) {
    const sharedUsageKey = 'shared:xxxxx'
    for (const provider of [...side.front, ...side.back]) {
      if (!resolution.unownXProviderIds.includes(provider.instanceId)) continue
      provider.abilityUses = { ...provider.abilityUses, [sharedUsageKey]: state.turnNumber }
    }
    recordCoinFlipEvent(state, {
      sourceId: attacker.instanceId,
      side: sideKey,
      results: resolution.abilityCoinFlips.results,
      heads: resolution.abilityCoinFlips.heads,
      tails: resolution.abilityCoinFlips.tails,
      purpose: 'effect',
    })
  }
  const opponentSideKey = sideKey === 'player' ? 'opponent' : 'player'
  const targetSideKey = [...side.front, ...side.back].some((card) => card.instanceId === target.instanceId)
    ? sideKey
    : opponentSideKey
  const redirectedTargetDamage = redirectTcgBattleBenchGuardDamage(state, sideKey, targetSideKey, target, resolution.targetDamage, attacker.instanceId)
  const targetDamageApplied = Math.max(0, resolution.targetDamage - redirectedTargetDamage)
  const targetWasActive = state[targetSideKey].front.some((card) => card.instanceId === target.instanceId)
  applyAttackDamageToCard(state, sideKey, attacker.instanceId, targetSideKey, target, targetDamageApplied)
  if (
    resolution.targetDamage > 0 &&
    target.incomingAttackModifier?.kind === 'coinPreventDamage' &&
    target.incomingAttackModifier.persistent
  ) {
    target.incomingAttackModifier = undefined
  }
  getTemporaryEffects(target).lastIncomingAttackDamage = targetDamageApplied
  if (targetDamageApplied > 0 && targetWasActive) {
    getTemporaryEffects(target).wasDamagedByAttackAsActiveLastTurn = true
  }
  if (attack.name.toLowerCase() === 'night eyes') {
    const history = getTemporaryEffects(target).lastNightEyesAttackBySide || {}
    history[sideKey] = 2
    getTemporaryEffects(target).lastNightEyesAttackBySide = history
  }
  if (targetDamageApplied > 0 || attack.name.toLowerCase() === 'midnight eyes') {
    recordTcgBattleAttackHit(target, sideKey)
  }
  const enteiBurningRoar = targetSideKey !== sideKey && target.currentHp <= 0 && targetDamageApplied > 0 &&
    normalizeTcgBattleAbilityCardName(attacker.name) === 'entei' &&
    !isTcgBattleAbilitySuppressedByShadyTail(attacker, [state.player, state.opponent]) &&
    (attacker.abilities || []).find((ability) => normalizeTcgBattleAbilityText(ability.text).replace(/\s+/g, ' ').trim() === "whenever 1 of your opponent's pokemon is knocked out by damage from entei's attacks, discard the top 3 cards from your opponent's deck.")
  if (enteiBurningRoar) {
    const discarded = side.deck.splice(0, 3)
    side.discard.push(...discarded.map((card, index) => createTcgBattleCardState(card, side.discard.length + index)))
    state.log.unshift(`${attacker.name}'s ${enteiBurningRoar.name} discarded ${discarded.length} cards from the opponent's deck after Knocking Out ${target.name}.`)
  }
  const zoroarkAfterKnockout = targetSideKey !== sideKey && target.currentHp <= 0 && targetDamageApplied > 0 && !resolution.targetShuffledOnSurvival &&
    !isTcgBattleAbilitySuppressedByShadyTail(attacker, [state.player, state.opponent]) &&
    (attacker.abilities || []).find((ability) => ability.text.replace(/[’]/g, "'").toLowerCase().normalize('NFD').replace(/\p{Diacritic}/gu, '').replace(/\s+/g, ' ').trim() === "if your opponent's pokemon is knocked out by damage from this pokemon's attacks, during your opponent's next turn, prevent all damage from—and effects of—attacks done to this pokemon.")
  if (zoroarkAfterKnockout) {
    attacker.incomingAttackModifier = { kind: 'preventAllEffects', remainingOpponentTurns: 1 }
    state.log.unshift(`${attacker.name}'s ${zoroarkAfterKnockout.name} prevents damage and effects from attacks during the opponent's next turn.`)
  }
  if (resolution.targetShuffledOnSurvival && target.currentHp <= 0) {
    const owner = state[targetSideKey]
    owner.front = owner.front.filter((card) => card.instanceId !== target.instanceId)
    owner.back = owner.back.filter((card) => card.instanceId !== target.instanceId)
    owner.deck.push(...(target.evolutionStack || []).map((card) => ({ ...card })), toTcgBattleCardSummary(target))
    shuffleTcgBattleDeck(owner)
    compactTcgBattleBoard(owner)
    blockTargetEffects = true
    state.log.unshift(`${target.name}'s Time Travel flipped heads and shuffled it and its Evolution cards into its owner's deck instead of being Knocked Out.`)
  }
  const fleeAbilityUsed = resolution.targetDamage > 0 && target.currentHp > 0 &&
    state[targetSideKey].front.some((card) => card.instanceId === target.instanceId) &&
    !isTcgBattleAbilitySuppressedByShadyTail(target, [state.player, state.opponent]) &&
    !target.statusConditions?.some((status) => ['asleep', 'confused', 'paralyzed'].includes(status)) &&
    (target.abilities || []).some((ability) => {
      const text = ability.text.replace(/[’]/g, "'").toLowerCase().normalize('NFD').replace(/\p{Diacritic}/gu, '').replace(/pokémon/g, 'pokemon').replace(/\s+/g, ' ').trim()
      return text === "if an attack does damage to misty's tentacruel while it's your active pokemon, you may switch it with 1 of your benched pokemon, which prevents all other effects of that attack on misty's tentacruel. this power can't be used if misty's tentacruel is already asleep, confused, or paralyzed."
    })
  if (fleeAbilityUsed) {
    const replacement = state[targetSideKey].back.filter((card) => card.currentHp > 0).sort((a, b) => b.currentHp - a.currentHp || b.hp - a.hp)[0]
    if (replacement && swapTcgBattleCards(state, targetSideKey, target, replacement.instanceId, true)) {
      blockTargetEffects = true
      state.log.unshift(`${target.name}'s Flee switched it with ${replacement.name}, preventing the attack's other effects on ${target.name}.`)
    }
  }
  if (resolution.benchDamage && resolution.benchDamage.length > 0) {
    for (const benchHit of resolution.benchDamage) {
      if (blockTargetEffects && benchHit.targetSide !== sideKey && benchHit.targetId === target.instanceId) continue
      const hitCard = [...state[benchHit.targetSide].front, ...state[benchHit.targetSide].back].find(
        (card) => card.instanceId === benchHit.targetId && card.currentHp > 0,
      )
      if (!hitCard) continue
      const redirectedDamage = redirectTcgBattleBenchGuardDamage(state, sideKey, benchHit.targetSide, hitCard, benchHit.damage, attacker.instanceId)
      const targetDamage = Math.max(0, benchHit.damage - redirectedDamage)
      applyAttackDamageToCard(state, sideKey, attacker.instanceId, benchHit.targetSide, hitCard, targetDamage)
      if (targetDamage > 0) recordTcgBattleAttackHit(hitCard, sideKey)
    }
  }
  if (resolution.counterDamage && resolution.counterDamage.length > 0) {
    for (const counterHit of resolution.counterDamage) {
      if (blockTargetEffects && counterHit.targetSide !== sideKey && counterHit.targetId === target.instanceId) continue
      const sideState = state[counterHit.targetSide]
      const allCards = [...sideState.front, ...sideState.back]
      const hitCard = allCards.find(
        (card) => card.instanceId === counterHit.targetId && card.currentHp > 0,
      )
      if (!hitCard) continue
      if (counterHit.targetSide !== sideKey && isTcgBattleBenchDamageCounterBlockedByAbility(hitCard, counterHit.targetSide, state, attacker)) continue
      applyAttackDamageToCard(state, sideKey, attacker.instanceId, counterHit.targetSide, hitCard, counterHit.damage)
      if (counterHit.damage > 0) recordTcgBattleAttackHit(hitCard, sideKey)
    }
  }
  let healedByAttack = false
  if (resolution.healing && resolution.healing.length > 0) {
    for (const heal of resolution.healing) {
      if (blockTargetEffects && heal.targetSide !== sideKey && heal.targetId === target.instanceId) continue
      const sideState = state[heal.targetSide]
      const allCards = [...sideState.front, ...sideState.back]
      const healCard = allCards.find(
        (card) => card.instanceId === heal.targetId && card.currentHp > 0,
      )
      if (!healCard) continue
      const previousHp = healCard.currentHp
      if (!isTcgBattleHealingPrevented(state)) {
      if (!isTcgBattleHealingPrevented(state)) {
        healCard.currentHp = Math.min(
          healCard.hp,
          healCard.currentHp + getTcgBattleAbilityHealingAmount(healCard, heal.amount),
        )
      }
      }
      if (healCard.currentHp > previousHp) {
        healedByAttack = true
        getTemporaryEffects(healCard).healedTurnNumber = state.turnNumber
        getTemporaryEffects(healCard).healedBySide = sideKey
      }
    }
  }

  let selfDamage = resolution.selfDamage
  if (resolution.selfKnockOut && attacker.currentHp - selfDamage > 0) {
    selfDamage += attacker.currentHp - selfDamage
  }
  if (selfDamage > 0) {
    attacker.currentHp = Math.max(0, attacker.currentHp - selfDamage)
    recordDamageEvent(state, {
      sourceId: attacker.instanceId,
      targetId: attacker.instanceId,
      targetSide: sideKey,
      damage: selfDamage,
      reason: 'self',
    })
  }
  if (resolution.incomingReflectedDamage && attacker.currentHp > 0) {
    const reflected = Math.min(attacker.currentHp, resolution.incomingReflectedDamage)
    attacker.currentHp -= reflected
    recordDamageEvent(state, {
      sourceId: target.instanceId,
      targetId: attacker.instanceId,
      targetSide: sideKey,
      damage: reflected,
      reason: 'self',
    })
  }
  if (
    targetReflectDamage &&
    resolution.targetDamage > 0 &&
    attacker.currentHp > 0
  ) {
    let reflectDamage = true
    if (targetReflectDamage.coinGate) {
      const result = flipTcgBattleCoinForSide(state, state.activeSide)
      recordCoinFlipEvent(state, {
        sourceId: target.instanceId,
        side: sideKey,
        results: [result],
        heads: result === 'heads' ? 1 : 0,
        tails: result === 'tails' ? 1 : 0,
        purpose: 'effect',
      })
      reflectDamage = typeof targetReflectDamage.coinGate === 'string'
        ? result === targetReflectDamage.coinGate
        : result === targetReflectDamage.coinGate.result && targetReflectDamage.coinGate.minimum <= 1
    }
    if (reflectDamage) {
      const reflected = Math.min(
        attacker.currentHp,
        targetReflectDamage.reflectFixedDamage ??
          resolution.targetDamage * (targetReflectDamage.damageMultiplier || 1),
      )
      attacker.currentHp -= reflected
      recordDamageEvent(state, {
        sourceId: target.instanceId,
        targetId: attacker.instanceId,
        targetSide: sideKey,
        damage: reflected,
        reason: 'self',
      })
    }
  }
  if (targetHadDestinyBond && target.currentHp <= 0 && attacker.currentHp > 0) {
    const bondedDamage = attacker.currentHp
    attacker.currentHp = 0
    recordDamageEvent(state, {
      sourceId: target.instanceId,
      targetId: attacker.instanceId,
      targetSide: sideKey,
      damage: bondedDamage,
      reason: 'self',
    })
  }
  const statusEvents = applyTcgBattleStatusConditions(
    state,
    sideKey,
    attacker.instanceId,
    target.instanceId,
    blockTargetEffects
      ? resolution.statusConditions?.filter(
          (status) => status.target === 'self',
        )
      : resolution.statusConditions,
  )
  recordStatusEvents(
    state,
    statusEvents.map(({ id: _id, ...event }) => event),
  )
  if (resolution.protection && resolution.protection.length > 0) {
    for (const protection of resolution.protection) {
      if (blockTargetEffects && protection.targetSide !== sideKey && protection.targetId === target.instanceId) continue
      const sideState = state[protection.targetSide]
      const allCards = [...sideState.front, ...sideState.back]
      const protectedCard = allCards.find(
        (card) => card.instanceId === protection.targetId && card.currentHp > 0,
      )
      if (!protectedCard) continue
      protectedCard.incomingAttackModifier = protection.modifier
    }
  }
  const specialEffectKnockoutIds = applyTcgBattleSpecialEffects({
    state,
    sideKey,
    attacker,
    target,
    paidAttackCost: energyCost,
    attackName: attack.name,
    attackIgnoresTargetEffects,
    choice,
    resolution,
    blockTargetEffects,
    healedByAttack,
  })
  const attackDamageEvents = (state.lastDamageEvents || []).slice(damageEventStartIndex)
  const attackStatusEvents = (state.lastStatusEvents || []).slice(statusEventStartIndex)
  applyTcgBattleReactiveAbilities(state, defendingSide, attackDamageEvents, attackStatusEvents)
  const grudgeKnockoutIds = new Set(
    attackDamageEvents
      .filter((event) => event.targetSide === defendingSide && event.reason === 'attack')
      .map((event) => event.targetId),
  )
  for (const grudgeCard of [...state[defendingSide].front, ...state[defendingSide].back]) {
    if (
      !grudgeKnockoutIds.has(grudgeCard.instanceId) ||
      grudgeCard.currentHp > 0 ||
      !grudgeCard.temporaryEffects?.discardEnergyOnKnockout
    ) continue
    delete grudgeCard.temporaryEffects.discardEnergyOnKnockout
    if (side.energy > 0) {
      side.energy -= 1
      state.log.unshift(`${grudgeCard.name}'s Little Grudge discarded 1 Energy from the attacking side.`)
    }
  }
  const defendingCards = [...state[defendingSide].front, ...state[defendingSide].back]
  const knockedOutByAttack = (state.lastDamageEvents || [])
    .slice(damageEventStartIndex)
    .some((event) =>
      event.targetSide === defendingSide &&
      event.reason === 'attack' &&
      defendingCards.some((card) => card.instanceId === event.targetId && card.currentHp <= 0),
    ) || specialEffectKnockoutIds.size > 0 || (
      resolution.specialEffects?.some((rule) => rule.kind === 'knockOutTarget') === true &&
      defendingCards.some((card) => card.instanceId === target.instanceId && card.currentHp <= 0)
    )
  const knockedOutByAttackIds = new Set(
    (state.lastDamageEvents || [])
      .slice(damageEventStartIndex)
      .filter((event) => event.targetSide === defendingSide && event.reason === 'attack')
      .map((event) => event.targetId),
  )
  for (const id of specialEffectKnockoutIds) knockedOutByAttackIds.add(id)
  if (resolution.specialEffects?.some((rule) => rule.kind === 'knockOutTarget') && target.currentHp <= 0) {
    knockedOutByAttackIds.add(target.instanceId)
  }
  const knockedOutByDamageIds = new Set((state.lastDamageEvents || []).slice(damageEventStartIndex)
    .filter((event) => event.targetSide === defendingSide && event.reason === 'attack' && event.damage > 0)
    .map((event) => event.targetId))
  const extraPrizeAbilityActive = !isTcgBattleAbilitySuppressedByShadyTail(attacker, [state.player, state.opponent])
  for (const card of defendingCards) {
    const extraPrizeFromAbility = extraPrizeAbilityActive && hasTcgBattleExtraPrizeForAttackKnockout(attacker, card)
    if (!knockedOutByDamageIds.has(card.instanceId) || card.currentHp > 0 || !(extraPrizeFromAbility || state[sideKey].extraPrizeForDamageKnockout)) continue
    card.temporaryEffects = { ...card.temporaryEffects, extraKnockoutCountOnFaint: 1 }
  }
  const wonderKissTargetIsActiveKnockout = knockedOutByAttackIds.has(target.instanceId) && target.currentHp <= 0 && state[defendingSide].front.some((card) => card.instanceId === target.instanceId)
  if (wonderKissTargetIsActiveKnockout) {
    const wonderKissSource = [...state[sideKey].front, ...state[sideKey].back].find((card) =>
      card.currentHp > 0 && hasTcgBattleWonderKiss(card) && !isTcgBattleAbilitySuppressedByShadyTail(card, [state.player, state.opponent]),
    )
    if (wonderKissSource) {
      const result = flipTcgBattleCoinForSide(state, state.activeSide)
      recordCoinFlipEvent(state, { sourceId: wonderKissSource.instanceId, side: sideKey, results: [result], heads: result === 'heads' ? 1 : 0, tails: result === 'tails' ? 1 : 0, purpose: 'effect' })
      if (result === 'heads') {
        target.temporaryEffects = { ...target.temporaryEffects, extraKnockoutCountOnFaint: (target.temporaryEffects?.extraKnockoutCountOnFaint || 0) + 1 }
        state.log.unshift(`${wonderKissSource.name}'s Wonder Kiss flipped heads; the Knock Out awards 1 extra Prize equivalent.`)
      } else {
        state.log.unshift(`${wonderKissSource.name}'s Wonder Kiss flipped tails; no extra Prize was awarded.`)
      }
    }
  }
  for (const card of defendingCards) {
    if (!knockedOutByDamageIds.has(card.instanceId) || card.currentHp > 0) continue
    const allSides = [state.player, state.opponent]
    let coinPrizeReduction = 0
    if (hasTcgBattleCoinFlipKnockoutPrizeReduction(card) && !isTcgBattleAbilitySuppressedByShadyTail(card, allSides)) {
      const result = flipTcgBattleCoinForSide(state, state.activeSide)
      recordCoinFlipEvent(state, { sourceId: card.instanceId, side: defendingSide, results: [result], heads: result === 'heads' ? 1 : 0, tails: result === 'tails' ? 1 : 0, purpose: 'effect' })
      if (result === 'heads') {
        coinPrizeReduction = 1
        if (hasTcgBattleShuffleIntoDeckOnKnockout(card)) card.temporaryEffects = { ...card.temporaryEffects, returnToDeckOnKnockout: true }
      }
      state.log.unshift(`${card.name}'s Knockout Ability flipped ${result}${result === 'heads' ? '; the opponent takes no Prize equivalent.' : '; the opponent takes the normal Prize equivalent.'}`)
    }
    const prizeReduction = Math.max(getTcgBattleKnockoutPrizeReduction(attacker, card, state[defendingSide], allSides), coinPrizeReduction)
    if (prizeReduction > 0) card.temporaryEffects = { ...card.temporaryEffects, knockoutPrizeReductionOnFaint: prizeReduction }
  }
  const hasLostZoneKnockoutAbility = !isTcgBattleAbilitySuppressedByShadyTail(attacker, [state.player, state.opponent]) && (attacker.abilities || []).some((ability) =>
    ability.text.replace(/[’]/g, "'").toLowerCase().normalize('NFD').replace(/\p{Diacritic}/gu, '').replace(/\s+/g, ' ').trim() === "if your opponent's pokemon is knocked out by damage from this pokemon's attacks, put that pokemon and all cards attached to it in the lost zone instead of the discard pile.",
  )
  if (hasLostZoneKnockoutAbility) {
    const damageKnockoutIds = new Set((state.lastDamageEvents || []).slice(damageEventStartIndex)
      .filter((event) => event.targetSide === defendingSide && event.reason === 'attack' && defendingCards.some((card) => card.instanceId === event.targetId && card.currentHp <= 0))
      .map((event) => event.targetId))
    for (const card of defendingCards) {
      if (!damageKnockoutIds.has(card.instanceId)) continue
      card.temporaryEffects = { ...card.temporaryEffects, lostZoneOnKnockout: true }
    }
  }
  const hasActiveGengarLostZoneAbility = state[sideKey].front.some((provider) =>
    provider.currentHp > 0 && normalizeTcgBattleAbilityCardName(provider.name) === 'gengar' &&
    !isTcgBattleAbilitySuppressedByShadyTail(provider, [state.player, state.opponent]) &&
    (provider.abilities || []).some((ability) =>
      ability.text.replace(/[’]/g, "'").toLowerCase().normalize('NFD').replace(/\p{Diacritic}/gu, '').replace(/\s+/g, ' ').trim() ===
        "as long as gengar is your active pokemon, if any of your opponent's pokemon would be knocked out, put that pokemon in the lost zone instead of discarding. (discard all cards attached to that pokemon.)",
    ),
  )
  if (hasActiveGengarLostZoneAbility) {
    for (const card of defendingCards) {
      if (!knockedOutByAttackIds.has(card.instanceId) || card.currentHp > 0) continue
      card.temporaryEffects = { ...card.temporaryEffects, lostZoneOnKnockout: true }
    }
  }
  for (const card of defendingCards) {
    const knockedOutByDamage = knockedOutByAttackIds.has(card.instanceId) && card.currentHp <= 0 &&
      (state.lastDamageEvents || []).slice(damageEventStartIndex).some((event) =>
        event.targetSide === defendingSide && event.targetId === card.instanceId && event.reason === 'attack' && event.damage > 0,
      )
    const knockedOutByAttack = knockedOutByAttackIds.has(card.instanceId) && card.currentHp <= 0
    if (!knockedOutByAttack || isTcgBattleAbilitySuppressedByShadyTail(card, [state.player, state.opponent])) continue
    const waterRescueProvider = [...state[defendingSide].front, ...state[defendingSide].back].find((provider) =>
      provider.currentHp > 0 && normalizeTcgBattleAbilityCardName(provider.name) === 'floatzel gl lv.x' && !isTcgBattleAbilitySuppressedByShadyTail(provider, [state.player, state.opponent]) &&
      (provider.abilities || []).some((ability) => ability.text.replace(/[’]/g, "'").toLowerCase().normalize('NFD').replace(/\p{Diacritic}/gu, '').replace(/pokémon/g, 'pokemon').replace(/\s+/g, ' ').trim() === "whenever any of your water pokemon (excluding any floatzel gl) is knocked out by damage from your opponent's attack, you may put that pokemon and all cards that were attached to it from your discard pile into your hand."),
    )
    if (knockedOutByDamage && card.types.some((type) => normalizeTcgBattleAbilityCardName(type) === 'water') && !normalizeTcgBattleAbilityCardName(card.name).startsWith('floatzel gl') && waterRescueProvider) {
      card.temporaryEffects = { ...card.temporaryEffects, rescueEvolutionStackToHandOnKnockout: true }
      state.log.unshift(`${waterRescueProvider.name}'s Water Rescue returned ${card.name} and its evolution stack to its owner's hand.`)
      continue
    }
    const returnsToHand = (card.abilities || []).some((ability) => {
      const text = ability.text.replace(/[’]/g, "'").toLowerCase().normalize('NFD').replace(/\p{Diacritic}/gu, '').replace(/\s+/g, ' ').trim()
      const rocketMoltresRebirth = text === "when rocket's moltres is knocked out, you may return it to your hand after discarding it. this power can't be used if rocket's moltres is asleep, confused, or paralyzed when it is knocked out."
      const rebirthBlocked = card.statusConditions?.some((status) => ['asleep', 'confused', 'paralyzed'].includes(status))
      const standardReturn = knockedOutByDamage && /^if this pokemon is knocked out by damage from (?:an attack from your opponent's pokemon|an opponent's attack), put it into your hand instead of the discard pile\. \(discard (?:all cards attached to it|all attached cards)\.\)$/.test(text)
      return standardReturn || rocketMoltresRebirth && !rebirthBlocked && normalizeTcgBattleAbilityCardName(card.name) === 'rocketsmoltres'
    })
    if (returnsToHand) card.temporaryEffects = { ...card.temporaryEffects, returnToHandOnKnockout: true }
  }
  const knockedOutNames = defendingCards
    .filter((card) => knockedOutByAttackIds.has(card.instanceId) && card.currentHp <= 0)
    .map((card) => card.name)
  const knockedOutTypes = [...new Set(defendingCards
    .filter((card) => knockedOutByAttackIds.has(card.instanceId) && card.currentHp <= 0 &&
      (state.lastDamageEvents || []).slice(damageEventStartIndex).some((event) => event.targetId === card.instanceId && event.targetSide === defendingSide && event.reason === 'attack' && event.damage > 0))
    .flatMap((card) => card.types))]
  const knockedOutRuleBox = defendingCards.some((card) => knockedOutByAttackIds.has(card.instanceId) && card.currentHp <= 0 && card.subtypes.some((subtype) => ['ex', 'gx'].includes(subtype.toLowerCase())))
  const knockedOutGrassPokemon = defendingCards.some((card) => card.types.some((type) => normalizeTcgBattleAbilityText(type) === 'grass') && knockedOutByAttackIds.has(card.instanceId) && card.currentHp <= 0 &&
    (state.lastDamageEvents || []).slice(damageEventStartIndex).some((event) => event.targetId === card.instanceId && event.targetSide === defendingSide && event.reason === 'attack' && event.damage > 0))
  const previousTurnKnockout = state.lastOpponentAttackKnockout?.[defendingSide]
  state.lastOpponentAttackKnockout = {
    ...state.lastOpponentAttackKnockout,
    [defendingSide]: {
      turnNumber: defendingSideTurnNumber,
      knockedOut: Boolean(previousTurnKnockout?.knockedOut || knockedOutByAttack),
      knockedOutNames: [...new Set([...(previousTurnKnockout?.knockedOutNames || []), ...knockedOutNames])],
      knockedOutTypes: [...new Set([...(previousTurnKnockout?.knockedOutTypes || []), ...knockedOutTypes])],
      knockedOutRuleBox: Boolean(previousTurnKnockout?.knockedOutRuleBox || knockedOutRuleBox),
      knockedOutGrassPokemon: Boolean(previousTurnKnockout?.knockedOutGrassPokemon || knockedOutGrassPokemon),
    },
  }
  clearSourceLinkedControlsForInactiveSources(state)

  if (
    attacker.temporaryEffects?.nextAttackBuff?.attackName === '*' ||
    attacker.temporaryEffects?.nextAttackBuff?.attackName.toLowerCase() === attack.name.toLowerCase() ||
    attacker.temporaryEffects?.nextAttackBuff?.attackNames?.some((name) => name.toLowerCase() === attack.name.toLowerCase())
  ) {
    delete attacker.temporaryEffects.nextAttackBuff
  }
  if (attacker.temporaryEffects?.attackCoinCountOverride?.attackName.toLowerCase() === attack.name.toLowerCase()) {
    delete attacker.temporaryEffects.attackCoinCountOverride
  }
  if (attacker.temporaryEffects?.lastIncomingAttackDamage !== undefined) {
    delete attacker.temporaryEffects.lastIncomingAttackDamage
  }

  syncTcgBattleDittoTransform(state)
  state.consecutivePasses = 0
  const coinSummary = resolution.coinFlips
    ? ` after ${resolution.coinFlips.heads} heads and ${resolution.coinFlips.tails} tails`
    : ''
  const selfSummary =
    selfDamage > 0 ? ` ${attacker.name} took ${selfDamage} recoil.` : ''
  const energyDiscardSummary =
    applicableEnergyDiscards && applicableEnergyDiscards.length > 0
      ? ` ${formatEnergyDiscardSummary(sideKey, applicableEnergyDiscards)}`
      : ''
  const statusSummary =
    resolution.statusConditions && resolution.statusConditions.length > 0
      ? ` ${resolution.statusConditions
          .map((status) => {
            const label =
              status.target === 'self'
                ? sideKey === 'player'
                  ? 'Your active Pokemon'
                  : "Opponent's active Pokemon"
                : sideKey === 'player'
                  ? "Opponent's active Pokemon"
                  : 'Your active Pokemon'
            return `${label} is now ${formatStatusNames(status.statuses)}.`
          })
          .join(' ')}`
      : ''
  const healingSummary =
    resolution.healing && resolution.healing.length > 0
      ? ` Healed ${resolution.healing.reduce((sum, heal) => sum + heal.amount, 0)} total HP.`
      : ''
  state.log.unshift(
    `${sideKey === 'player' ? 'You' : 'Opponent'} used ${attacker.name}'s ${attack.name} for ${resolution.targetDamage} damage${coinSummary}.${selfSummary}${energyDiscardSummary}${statusSummary}${healingSummary}`,
  )
}

function hasTcgBattleAttackTwiceAbility(
  state: TcgBattleState,
  sideKey: TcgBattleSide,
  attacker: TcgBattleCardState,
) {
  if (isTcgBattleAbilitySuppressedByShadyTail(attacker, [state.player, state.opponent])) return false
  const raichuLinkLightning = normalizeTcgBattleAbilityCardName(attacker.name).replace(/[^a-z0-9]/g, '') === 'raichulvx' && !attacker.statusConditions?.length && (attacker.abilities || []).some((ability) => ability.text.replace(/[’]/g, "'").toLowerCase().normalize('NFD').replace(/\p{Diacritic}/gu, '').replace(/pokémon/g, 'pokemon').replace(/\s+/g, ' ').trim() === "once during your turn, when you put raichu lv.x onto raichu and use voltage shoot, you may use another attack of raichu afterward. this power can't be used if raichu is affected by a special condition.")
  return (attacker.abilities || []).some((ability) => {
    const text = ability.text.replace(/[’]/g, "'").toLowerCase().normalize('NFD').replace(/\p{Diacritic}/gu, '').replace(/\s+/g, ' ').trim()
    return /^this pokemon may attack twice a turn\./.test(text) || text === "this pokemon may attack twice each turn. if the first attack knocks out your opponent's active pokemon, you may attack again after your opponent chooses a new active pokemon."
  }) || raichuLinkLightning
    ? state[sideKey].front.some((card) => card.instanceId === attacker.instanceId)
    : false
}

function hasTcgBattleRaichuLinkLightning(attacker: TcgBattleCardState) {
  return normalizeTcgBattleAbilityCardName(attacker.name).replace(/[^a-z0-9]/g, '') === 'raichulvx' && !attacker.statusConditions?.length && (attacker.abilities || []).some((ability) => ability.text.replace(/[’]/g, "'").toLowerCase().normalize('NFD').replace(/\p{Diacritic}/gu, '').replace(/pokémon/g, 'pokemon').replace(/\s+/g, ' ').trim() === "once during your turn, when you put raichu lv.x onto raichu and use voltage shoot, you may use another attack of raichu afterward. this power can't be used if raichu is affected by a special condition.")
}

function hasTcgBattleKnockoutGatedAttackTwiceAbility(attacker: TcgBattleCardState): boolean {
  return (attacker.abilities || []).some((ability) => ability.text.replace(/[’]/g, "'").toLowerCase().normalize('NFD').replace(/\p{Diacritic}/gu, '').replace(/\s+/g, ' ').trim() === "this pokemon may attack twice each turn. if the first attack knocks out your opponent's active pokemon, you may attack again after your opponent chooses a new active pokemon.")
}

function applyTcgBattleEmperorAura(state: TcgBattleState, sideKey: TcgBattleSide, evolvedCard: TcgBattleCardState) {
  const expected = "once during your turn (before your attack), when you play empoleon from your hand to evolve 1 of your active pokemon, you may use this power. your opponent can't attach any energy cards from his or her hand to his or her pokemon during your opponent's next turn."
  const ability = evolvedCard.abilities?.find((candidate) => candidate.name === 'Emperor Aura' && candidate.text.replace(/[’]/g, "'").toLowerCase().replace(/\s+/g, ' ').trim() === expected)
  if (!ability || !state[sideKey].front.some((card) => card.instanceId === evolvedCard.instanceId) || isTcgBattleAbilitySuppressedByShadyTail(evolvedCard, [state.player, state.opponent])) return
  const blockedSide = sideKey === 'player' ? 'opponent' : 'player'
  state.energyChargeBlocked = { side: blockedSide, turnNumber: getNextTcgBattleTurnNumber(state.turnNumber, sideKey, blockedSide) }
  state.log.unshift(`${evolvedCard.name}'s ${ability.name} prevents ${blockedSide === 'player' ? 'you' : 'the opponent'} from charging Energy on their next turn.`)
}

function applyTcgBattleEvolutionaryGas(state: TcgBattleState, sideKey: TcgBattleSide, evolvedCard: TcgBattleCardState) {
  const expected = "once during your turn (before your attack), when you play skuntank from your hand to evolve 1 of your active pokemon, you may choose 1 of the defending pokemon. if that pokemon tries to attack during your opponent's next turn, that attack does nothing."
  const ability = evolvedCard.abilities?.find((candidate) => candidate.name === 'Evolutionary Gas' && candidate.text.replace(/[’]/g, "'").toLowerCase().replace(/\s+/g, ' ').trim() === expected)
  const opposingSide = sideKey === 'player' ? 'opponent' : 'player'
  const target = state[opposingSide].front.find((card) => card.currentHp > 0)
  if (!ability || !state[sideKey].front.some((card) => card.instanceId === evolvedCard.instanceId) || !target || isTcgBattleAbilitySuppressedByShadyTail(evolvedCard, [state.player, state.opponent])) return
  target.temporaryEffects = { ...target.temporaryEffects, cannotAttack: { remainingTurns: 2 } }
  state.log.unshift(`${evolvedCard.name}'s ${ability.name} prevents ${target.name} from attacking next turn.`)
}

function applyTcgBattleEvolutionStatusEffect(state: TcgBattleState, sideKey: TcgBattleSide, evolvedCard: TcgBattleCardState, targetId?: string): boolean {
  const effect = getTcgBattleEvolutionStatusEffect(evolvedCard)
  if (!effect || isTcgBattleAbilitySuppressedByShadyTail(evolvedCard, [state.player, state.opponent])) return false
  if (effect.coinFlip) {
    const result = flipTcgBattleCoinForSide(state, state.activeSide)
    recordCoinFlipEvent(state, { sourceId: evolvedCard.instanceId, side: sideKey, results: [result], heads: result === 'heads' ? 1 : 0, tails: result === 'tails' ? 1 : 0, purpose: 'effect' })
    if (result === 'tails') {
      state.log.unshift(`${evolvedCard.name}'s ${effect.abilityName} flipped tails.`)
      return true
    }
  }
  const opposingSideKey = sideKey === 'player' ? 'opponent' : 'player'
  if (effect.bothActive) {
    const ownTarget = state[sideKey].front.find((card) => card.currentHp > 0)
    const opposingTarget = state[opposingSideKey].front.find((card) => card.currentHp > 0)
    if (!ownTarget || !opposingTarget) return false
    const ownEvents = applyTcgBattleStatusConditions(state, sideKey, evolvedCard.instanceId, ownTarget.instanceId, [{ target: 'self', statuses: effect.statuses }], true)
    const opposingEvents = applyTcgBattleStatusConditions(state, sideKey, evolvedCard.instanceId, opposingTarget.instanceId, [{ target: 'opponent', statuses: effect.statuses }], true)
    state.lastStatusEvents = [...ownEvents, ...opposingEvents].map((event) => ({ ...event, id: randomUUID() }))
    state.log.unshift(`${evolvedCard.name}'s ${effect.abilityName} made both Active Pokémon ${effect.statuses.join(' and ')}.`)
    return true
  }
  const target = state[opposingSideKey].front.find((card) => card.currentHp > 0 && (!effect.chooseDefending || !targetId || card.instanceId === targetId))
  if (!target) return false
  const events = applyTcgBattleStatusConditions(state, sideKey, evolvedCard.instanceId, target.instanceId, [{ target: 'opponent', statuses: effect.statuses }], true)
  if (effect.poisonBonus && target.statusConditions?.includes('poisoned')) {
    target.temporaryEffects = { ...target.temporaryEffects, poisonCheckupBonus: effect.poisonBonus }
  }
  state.lastStatusEvents = events.map((event) => ({ ...event, id: randomUUID() }))
  state.log.unshift(events.length
    ? `${evolvedCard.name}'s ${effect.abilityName}${effect.coinFlip ? ' flipped heads and' : ''} made ${target.name} ${effect.statuses.join(' and ')}.`
    : `${evolvedCard.name}'s ${effect.abilityName}${effect.coinFlip ? ' flipped heads but' : ''} could not affect ${target.name}.`)
  return true
}

function applyTcgBattleEvolutionAttackProtection(state: TcgBattleState, evolvedCard: TcgBattleCardState): boolean {
  const effect = getTcgBattleEvolutionAttackProtectionEffect(evolvedCard)
  if (!effect || isTcgBattleAbilitySuppressedByShadyTail(evolvedCard, [state.player, state.opponent])) return false
  evolvedCard.incomingAttackModifier = { kind: 'preventAllEffects', remainingOpponentTurns: 1, activeOnly: effect.activeOnly }
  state.log.unshift(`${evolvedCard.name}'s ${effect.abilityName} prevents all effects, including damage, from the opponent's attacks until the end of their next turn.`)
  return true
}

function applyTcgBattleEvolutionDevolution(state: TcgBattleState, sideKey: TcgBattleSide, evolvedCard: TcgBattleCardState): boolean {
  const effect = getTcgBattleEvolutionDevolutionEffect(evolvedCard)
  if (!effect || isTcgBattleAbilitySuppressedByShadyTail(evolvedCard, [state.player, state.opponent])) return false
  const opposingSideKey = sideKey === 'player' ? 'opponent' : 'player'
  const opposingSide = state[opposingSideKey]
  const devolved: string[] = []
  for (const target of [...opposingSide.front, ...opposingSide.back]) {
    const previousStage = target.evolutionStack?.at(-1)
    if (!previousStage || target.currentHp <= 0) continue
    const returnedCard = toTcgBattleCardSummary(target)
    const damage = target.hp - target.currentHp
    const restoredStack = target.evolutionStack!.slice(0, -1)
    const preserved = {
      instanceId: target.instanceId,
      currentHp: Math.max(0, previousStage.hp - damage),
      playedToBenchTurn: target.playedToBenchTurn,
      playedToFrontTurn: target.playedToFrontTurn,
      evolvedTurn: target.evolvedTurn,
      statusConditions: target.statusConditions,
      incomingAttackModifier: target.incomingAttackModifier,
      temporaryEffects: target.temporaryEffects,
      markers: target.markers,
      evolutionStack: restoredStack,
      abilityUses: target.abilityUses,
    }
    Object.assign(target, previousStage, preserved)
    opposingSide.hand.push(createTcgBattleCardState(returnedCard, opposingSide.hand.length))
    devolved.push(target.name)
  }
  state.log.unshift(devolved.length
    ? `${evolvedCard.name}'s ${effect.abilityName} devolved ${devolved.join(', ')} and returned their highest Evolution cards to the opponent's hand.`
    : `${evolvedCard.name}'s ${effect.abilityName} had no opposing evolved Pokémon to devolve.`)
  return true
}

function applyTcgBattleEvolutionShuffle(state: TcgBattleState, sideKey: TcgBattleSide, evolvedCard: TcgBattleCardState, targetId: string): boolean {
  const effect = getTcgBattleEvolutionShuffleEffect(evolvedCard)
  if (!effect || isTcgBattleAbilitySuppressedByShadyTail(evolvedCard, [state.player, state.opponent])) return false
  const opposingSideKey = sideKey === 'player' ? 'opponent' : 'player'
  const opposingSide = state[opposingSideKey]
  const target = [...opposingSide.front, ...opposingSide.back].find((card) => card.instanceId === targetId && card.currentHp > 0)
  if (!target) return false
  const result = flipTcgBattleCoinForSide(state, state.activeSide)
  recordCoinFlipEvent(state, { sourceId: evolvedCard.instanceId, side: sideKey, results: [result], heads: result === 'heads' ? 1 : 0, tails: result === 'tails' ? 1 : 0, purpose: 'effect' })
  if (result === 'tails') {
    state.log.unshift(`${evolvedCard.name}'s ${effect.abilityName} flipped tails; ${target.name} stayed in play.`)
    return true
  }
  opposingSide.front = opposingSide.front.filter((card) => card.instanceId !== targetId)
  opposingSide.back = opposingSide.back.filter((card) => card.instanceId !== targetId)
  opposingSide.deck.push(...(target.evolutionStack || []).map((card) => ({ ...card })), toTcgBattleCardSummary(target))
  shuffleTcgBattleDeck(opposingSide)
  compactTcgBattleBoard(opposingSide)
  if (opposingSideKey === 'opponent') promoteOpponentIfNeeded(state)
  else requirePlayerPromotionIfNeeded(state)
  state.log.unshift(`${evolvedCard.name}'s ${effect.abilityName} flipped heads and shuffled ${target.name} and its Evolution cards into the opponent's deck. Individual attached cards are not tracked.`)
  return true
}

function applyTcgBattleEvolutionDiscard(state: TcgBattleState, sideKey: TcgBattleSide, evolvedCard: TcgBattleCardState): boolean {
  const effect = getTcgBattleEvolutionDiscardEffect(evolvedCard)
  const opposingSideKey = sideKey === 'player' ? 'opponent' : 'player'
  const opposingSide = state[opposingSideKey]
  const target = opposingSide.front.find((card) => card.currentHp > 0)
  if (!effect || !target || isTcgBattleAbilitySuppressedByShadyTail(evolvedCard, [state.player, state.opponent])) return false
  const results: ('heads' | 'tails')[] = [flipTcgBattleCoinForSide(state, state.activeSide), flipTcgBattleCoinForSide(state, state.activeSide)]
  recordCoinFlipEvent(state, { sourceId: evolvedCard.instanceId, side: sideKey, results, heads: results.filter((result) => result === 'heads').length, tails: results.filter((result) => result === 'tails').length, purpose: 'effect' })
  if (results.every((result) => result === 'heads')) {
    opposingSide.front = opposingSide.front.filter((card) => card.instanceId !== target.instanceId)
    opposingSide.back = opposingSide.back.filter((card) => card.instanceId !== target.instanceId)
    const discardedCards = [...(target.evolutionStack || []), toTcgBattleCardSummary(target)]
    opposingSide.discard.push(...discardedCards.map((card, index) => {
      const discarded = createTcgBattleCardState(card, opposingSide.discard.length + index)
      discarded.currentHp = 0
      return discarded
    }))
    compactTcgBattleBoard(opposingSide)
    if (opposingSideKey === 'opponent') promoteOpponentIfNeeded(state)
    else requirePlayerPromotionIfNeeded(state)
    state.log.unshift(`${evolvedCard.name}'s ${effect.abilityName} flipped two heads and discarded the Defending Pokémon and its Evolution cards. It was not Knocked Out.`)
  } else {
    state.log.unshift(`${evolvedCard.name}'s ${effect.abilityName} did not flip two heads; the Defending Pokémon stayed in play.`)
  }
  return true
}

function applyTcgBattleEvolutionDamageAbility(
  state: TcgBattleState,
  sideKey: TcgBattleSide,
  evolvedCard: TcgBattleCardState,
  targetIds: string | string[],
): boolean {
  const effect = getTcgBattleEvolutionDamageEffect(evolvedCard)
  const requiredTargetCount = effect?.targetCount || 0
  const opposingSide = sideKey === 'player' ? 'opponent' : 'player'
  if (effect?.coinSpreadCount) {
    if (isTcgBattleAbilitySuppressedByShadyTail(evolvedCard, [state.player, state.opponent])) return false
    const results = Array.from({ length: effect.coinSpreadCount }, () => flipTcgBattleCoinForSide(state, state.activeSide))
    recordCoinFlipEvent(state, { sourceId: evolvedCard.instanceId, side: sideKey, results, heads: results.filter((result) => result === 'heads').length, tails: results.filter((result) => result === 'tails').length, purpose: 'effect' })
    const heads = results.filter((result) => result === 'heads').length
    const targets = state[opposingSide].back.filter((card) => card.currentHp > 0)
    for (const target of targets) target.currentHp -= heads * effect.amount
    state.log.unshift(`${evolvedCard.name}'s ${evolvedCard.abilities?.find((ability) => getTcgBattleEvolutionDamageEffect({ ...evolvedCard, abilities: [ability] }))?.name || 'Ability'} flipped ${results.join(', ')}; ${heads ? `it put ${heads} damage counter${heads === 1 ? '' : 's'} on each of ${targets.length} opposing Benched Pokémon` : 'it put no damage counters on the opposing Bench'}.`)
    return true
  }
  const selectedIds = effect?.allOpposing
    ? [...state[opposingSide].front, ...state[opposingSide].back].filter((card) => card.currentHp > 0).map((card) => card.instanceId)
    : Array.isArray(targetIds) ? targetIds : [targetIds]
  if (!effect || (!effect.allOpposing && selectedIds.length !== requiredTargetCount) || new Set(selectedIds).size !== selectedIds.length || isTcgBattleAbilitySuppressedByShadyTail(evolvedCard, [state.player, state.opponent])) return false
  const targets = selectedIds.map((targetId) => [...state[opposingSide].front, ...state[opposingSide].back].find((card) => card.instanceId === targetId && card.currentHp > 0 && (effect.targetRule !== 'pokemonExOrGx' || card.subtypes.some((subtype) => /(?:pokemon[- ]?)?(?:ex|gx)/i.test(subtype)))))
  if (targets.some((target) => !target)) return false
  if (effect.activeAmount !== undefined && effect.benchAmount !== undefined) {
    const activeTarget = (targets as TcgBattleCardState[]).find((target) => state[opposingSide].front.some((card) => card.instanceId === target.instanceId))
    const benchTarget = (targets as TcgBattleCardState[]).find((target) => state[opposingSide].back.some((card) => card.instanceId === target.instanceId))
    if (targets.length !== 2 || !activeTarget || !benchTarget) return false
    activeTarget.currentHp -= effect.activeAmount
    benchTarget.currentHp -= effect.benchAmount
    state.log.unshift(`${evolvedCard.name}'s Ability put ${effect.activeAmount / 10} damage counters on ${activeTarget.name} and ${effect.benchAmount / 10} damage counters on ${benchTarget.name}.`)
    return true
  }
  for (const target of targets as TcgBattleCardState[]) {
    const targetIsActive = state[opposingSide].front.some((card) => card.instanceId === target.instanceId)
    const damage = effect.applyWeaknessResistance
      ? applyTcgWeaknessAndResistance(evolvedCard, target, effect.amount, { targetIsActive, state, targetSide: opposingSide })
      : effect.amount
    target.currentHp -= damage
  }
  state.log.unshift(effect.counters
    ? `${evolvedCard.name}'s Ability put ${effect.amount / 10} damage counter${effect.amount === 10 ? '' : 's'} on ${targets.map((target) => target!.name).join(' and ')}.`
    : `${evolvedCard.name}'s ${evolvedCard.abilities?.find((ability) => getTcgBattleEvolutionDamageEffect({ ...evolvedCard, abilities: [ability] }))?.name || 'Ability'} dealt ${effect.amount} damage to ${targets.map((target) => target!.name).join(' and ')}, applying Weakness and Resistance.`)
  return true
}

function getTcgBattleEvolutionDeckDiscardAbilityIndex(card: Pick<TcgBattleCardState, 'abilities'>) {
  return card.abilities?.findIndex((ability) => {
    const text = ability.text.replace(/[’]/g, "'").toLowerCase().normalize('NFD').replace(/\p{Diacritic}/gu, '').replace(/\s+/g, ' ').trim()
    return /^once during your turn, when you play this pokemon from your hand to evolve 1 of your pokemon, you may use this ability\. you may also use this ability if this pokemon is in the active spot and is knocked out by damage from an attack from your opponent's pokemon\. discard the top 2 cards of your opponent's deck\.$/.test(text) ||
      /^(?:once during your turn, )?when you play (?:this pokemon|[a-z0-9 .'-]+) from your hand to evolve 1 of your pokemon(?: during your turn)?, you may discard the top \d+ cards (?:of|from) your opponent's deck\.$/.test(text)
      || /^when you play this pokemon from your hand to evolve 1 of your pokemon during your turn, you must flip a coin\. if heads, discard the top (\d+) cards (?:of|from) your opponent's deck\. if tails, discard the top (\d+) cards (?:of|from) your deck\.$/.test(text)
      || /^when you play this pokemon from your hand to evolve 1 of your pokemon during your turn, you must discard the top (\d+) cards of your deck\.$/.test(text)
  }) ?? -1
}

function applyTcgBattleEvolutionDeckDiscardAbility(state: TcgBattleState, sideKey: TcgBattleSide, evolvedCard: TcgBattleCardState) {
  const abilityIndex = getTcgBattleEvolutionDeckDiscardAbilityIndex(evolvedCard)
  if (abilityIndex < 0 || isTcgBattleAbilitySuppressedByShadyTail(evolvedCard, [state.player, state.opponent])) return false
  const opponentKey = sideKey === 'player' ? 'opponent' : 'player'
  const abilityText = evolvedCard.abilities![abilityIndex].text.toLowerCase()
  const ownDeckDiscard = abilityText.match(/must discard the top (\d+) cards of your deck\./)
  if (ownDeckDiscard) {
    const discarded = state[sideKey].deck.splice(0, Number(ownDeckDiscard[1]))
    state[sideKey].discard.push(...discarded.map((card, index) => createTcgBattleCardState(card, state[sideKey].discard.length + index)))
    evolvedCard.abilityUses = { ...evolvedCard.abilityUses, [`${abilityIndex}:${evolvedCard.abilities![abilityIndex].name}`]: state.turnNumber }
    state.log.unshift(`${evolvedCard.name}'s ${evolvedCard.abilities![abilityIndex].name} discarded ${discarded.length} cards from the top of its controller's deck.`)
    return true
  }
  const coinDiscard = abilityText.match(/must flip a coin\. if heads, discard the top (\d+) cards (?:of|from) your opponent's deck\. if tails, discard the top (\d+) cards (?:of|from) your deck\./)
  if (coinDiscard) {
    const result = flipTcgBattleCoinForSide(state, state.activeSide)
    recordCoinFlipEvent(state, { sourceId: evolvedCard.instanceId, side: sideKey, results: [result], heads: result === 'heads' ? 1 : 0, tails: result === 'tails' ? 1 : 0, purpose: 'effect' })
    const deckSideKey = result === 'heads' ? opponentKey : sideKey
    const discarded = state[deckSideKey].deck.splice(0, Number(coinDiscard[result === 'heads' ? 1 : 2]))
    state[deckSideKey].discard.push(...discarded.map((card, index) => createTcgBattleCardState(card, state[deckSideKey].discard.length + index)))
    evolvedCard.abilityUses = { ...evolvedCard.abilityUses, [`${abilityIndex}:${evolvedCard.abilities![abilityIndex].name}`]: state.turnNumber }
    state.log.unshift(`${evolvedCard.name}'s ${evolvedCard.abilities![abilityIndex].name} flipped ${result} and discarded ${discarded.length} cards from the ${deckSideKey} deck.`)
    return true
  }
  const discardCount = Number(abilityText.match(/discard the top (\d+) cards (?:of|from) your opponent's deck/)?.[1] || 2)
  const discarded = state[opponentKey].deck.splice(0, discardCount)
  state[opponentKey].discard.push(...discarded.map((card, index) => createTcgBattleCardState(card, state[opponentKey].discard.length + index)))
  evolvedCard.abilityUses = { ...evolvedCard.abilityUses, [`${abilityIndex}:${evolvedCard.abilities![abilityIndex].name}`]: state.turnNumber }
  state.log.unshift(`${evolvedCard.name}'s ${evolvedCard.abilities![abilityIndex].name} discarded ${discarded.length} card${discarded.length === 1 ? '' : 's'} from the ${opponentKey === 'player' ? 'player' : 'opponent'} deck.`)
  return true
}

function getTcgBattleEvolutionRandomHandDiscardAbilityIndex(card: Pick<TcgBattleCardState, 'abilities'>) {
  return card.abilities?.findIndex((ability) => {
    const text = normalizeTcgBattleAbilityText(ability.text).replace(/\s+/g, ' ').trim()
    return text === "when you play this pokemon from your hand to evolve 1 of your pokemon during your turn, you may discard a random card from your opponent's hand. if this pokemon is your active pokemon and is knocked out by damage from an opponent's attack, you may discard a random card from your opponent's hand." ||
      /^when you play this pokemon from your hand to evolve 1 of your pokemon during your turn, you may choose (?:a|2) random cards? from your opponent's hand\. your opponent reveals? (?:that card|those cards) and shuffles? (?:it|them) into (?:their|his or her) deck\.$/.test(text)
  }) ?? -1
}

function applyTcgBattleEvolutionRandomHandDiscard(state: TcgBattleState, sideKey: TcgBattleSide, evolvedCard: TcgBattleCardState) {
  const abilityIndex = getTcgBattleEvolutionRandomHandDiscardAbilityIndex(evolvedCard)
  if (abilityIndex < 0) return false
  if (isTcgBattleAbilitySuppressedByShadyTail(evolvedCard, [state.player, state.opponent])) return true
  const opponentKey = sideKey === 'player' ? 'opponent' : 'player'
  const opponent = state[opponentKey]
  const abilityText = normalizeTcgBattleAbilityText(evolvedCard.abilities?.[abilityIndex]?.text || '').replace(/\s+/g, ' ').trim()
  const shufflesHandCards = /shuffles? (?:them|it|that card) into (?:their|his or her) deck/.test(abilityText)
  const requestedCount = /choose 2 random cards/.test(abilityText) ? 2 : 1
  if (!opponent.hand.length) {
    state.log.unshift(`${evolvedCard.name}'s ${evolvedCard.abilities?.[abilityIndex]?.name || 'Ability'} had no card to discard from the opponent's hand.`)
    return true
  }
  const affected = []
  for (let index = 0; index < Math.min(requestedCount, opponent.hand.length); index += 1) {
    affected.push(opponent.hand.splice(Math.floor(Math.random() * opponent.hand.length), 1)[0])
  }
  if (shufflesHandCards) {
    opponent.deck.push(...affected.map(toTcgBattleCardSummary))
    shuffleTcgBattleDeck(opponent)
    state.log.unshift(`${evolvedCard.name}'s ${evolvedCard.abilities?.[abilityIndex]?.name || 'Ability'} revealed ${affected.map((card) => card.name).join(' and ')} from the opponent's hand and shuffled ${affected.length} card${affected.length === 1 ? '' : 's'} into their deck.`)
  } else {
    opponent.discard.push(...affected)
    state.log.unshift(`${evolvedCard.name}'s ${evolvedCard.abilities?.[abilityIndex]?.name || 'Ability'} discarded a random card from the opponent's hand.`)
  }
  return true
}

function isTcgBattleDiscardToHandPrevented(state: TcgBattleState, recoveringSideKey: TcgBattleSide): boolean {
  const opponentSide = state[recoveringSideKey === 'player' ? 'opponent' : 'player']
  return [...opponentSide.front, ...opponentSide.back].some((card) => card.currentHp > 0
    && normalizeTcgBattleAbilityCardName(card.name) === 'toedscruel'
    && !isTcgBattleAbilitySuppressedByShadyTail(card, [state.player, state.opponent])
    && card.abilities?.some((ability) => normalizeTcgBattleAbilityText(ability.text).replace(/\s+/g, ' ').trim() === "cards in your opponent's discard pile can't be put into their hand by an effect of your opponent's abilities or trainer cards."))
}

function applyTcgBattleEvolutionDiscardRecovery(
  state: TcgBattleState,
  sideKey: TcgBattleSide,
  evolvedCard: TcgBattleCardState,
  selectedIds: string[],
): boolean {
  const count = getTcgBattleEvolutionDiscardRecoveryCount(evolvedCard)
  if (!count || selectedIds.length < 1 || selectedIds.length > count || new Set(selectedIds).size !== selectedIds.length || isTcgBattleAbilitySuppressedByShadyTail(evolvedCard, [state.player, state.opponent]) || isTcgBattleDiscardToHandPrevented(state, sideKey)) return false
  const side = state[sideKey]
  const recovered = selectedIds.map((id) => side.discard.find((card) => card.instanceId === id))
  if (recovered.some((card) => !card)) return false
  const recoveredIds = new Set(selectedIds)
  side.discard = side.discard.filter((card) => !recoveredIds.has(card.instanceId))
  side.hand.push(...(recovered as TcgBattleCardState[]))
  state.log.unshift(`${evolvedCard.name}'s Ability returned ${recovered.length} Pokémon from the discard pile to the hand.`)
  return true
}

function applyTcgBattleEvolutionBenchSearch(
  state: TcgBattleState,
  sideKey: TcgBattleSide,
  evolvedCard: TcgBattleCardState,
  selectedIndices: string[],
): boolean {
  const count = getTcgBattleEvolutionBenchSearchCount(evolvedCard)
  const shedinjaSearch = hasTcgBattleEvolutionShedinjaSearch(evolvedCard)
  const shedinjaHandDiscard = hasTcgBattleEvolutionShedinjaHandDiscard(evolvedCard)
  const shedinjaDiscardSearch = hasTcgBattleEvolutionShedinjaDiscardSearch(evolvedCard)
  const namedSearchNames = getTcgBattleEvolutionNamedBenchSearchNames(evolvedCard)
  const side = state[sideKey]
  if (count < 1 || selectedIndices.length > count || new Set(selectedIndices).size !== selectedIndices.length || isTcgBattleAbilitySuppressedByShadyTail(evolvedCard, [state.player, state.opponent])) return false
  if (hasTcgBattleEvolutionOpponentDiscardBenchSearch(evolvedCard)) {
    if (!selectedIndices.length) return true
    const targetSideKey: TcgBattleSide = sideKey === 'player' ? 'opponent' : 'player'
    const targetSide = state[targetSideKey]
    const instanceId = selectedIndices[0]?.replace(/^opponent-discard:/, '')
    const index = targetSide.discard.findIndex((card) => card.instanceId === instanceId && card.subtypes.some((subtype) => subtype.toLowerCase() === 'basic'))
    if (selectedIndices.length !== 1 || !instanceId || !selectedIndices[0]?.startsWith('opponent-discard:') || index < 0 || getOpenTcgBattleBenchSlots(targetSide) < 1) return false
    const [card] = targetSide.discard.splice(index, 1)
    const benched = createTcgBattleCardState(toTcgBattleCardSummary(card), targetSide.back.length)
    targetSide.back.push(benched)
    const abilityIndex = evolvedCard.abilities?.findIndex((ability) => hasTcgBattleEvolutionOpponentDiscardBenchSearch({ ...evolvedCard, abilities: [ability] })) ?? -1
    const ability = evolvedCard.abilities?.[abilityIndex]
    if (ability && abilityIndex >= 0) evolvedCard.abilityUses = { ...evolvedCard.abilityUses, [`${abilityIndex}:${ability.name}`]: state.turnNumber }
    state.log.unshift(`${evolvedCard.name}'s ${ability?.name || 'Ability'} put ${benched.name} from the opponent's discard pile onto their Bench.`)
    return true
  }
  if (shedinjaHandDiscard) {
    if (!selectedIndices.length) return true
    if (selectedIndices.length !== 1 || getOpenTcgBattleBenchSlots(side) < 1) return false
    const abilityIndex = evolvedCard.abilities?.findIndex((ability) => hasTcgBattleEvolutionShedinjaHandDiscard({ ...evolvedCard, abilities: [ability] })) ?? -1
    const ability = evolvedCard.abilities?.[abilityIndex]
    if (!ability || abilityIndex < 0) return false
    const usageKey = `${abilityIndex}:${ability.name}`
    if (evolvedCard.abilityUses?.[usageKey] === state.turnNumber) return false
    const [zoneName, instanceId] = selectedIndices[0].split(':', 2)
    const zone = zoneName === 'hand' ? side.hand : zoneName === 'discard' ? side.discard : undefined
    const index = zone?.findIndex((card) => card.instanceId === instanceId) ?? -1
    if (!zone || index < 0 || normalizeTcgBattleAbilityCardName(zone[index].name).replace(/[^a-z0-9]/g, '') !== 'shedinja' || !canTcgBattlePutPokemonOnBench(side, zone[index])) return false
    const [card] = zone.splice(index, 1)
    const played = createTcgBattleCardState(toTcgBattleCardSummary(card), side.back.length)
    played.subtypes = ['Basic']
    side.back.push(played)
    evolvedCard.abilityUses = { ...evolvedCard.abilityUses, [usageKey]: state.turnNumber }
    state.log.unshift(`${evolvedCard.name}'s Ability put Shedinja from the ${zoneName} onto the Bench as a Basic Pokémon.`)
    return true
  }
  if (shedinjaDiscardSearch) {
    if (!selectedIndices.length) return true
    if (selectedIndices.length !== 1 || getOpenTcgBattleBenchSlots(side) < 1) return false
    const abilityIndex = evolvedCard.abilities?.findIndex((ability) => hasTcgBattleEvolutionShedinjaDiscardSearch({ ...evolvedCard, abilities: [ability] })) ?? -1
    const ability = evolvedCard.abilities?.[abilityIndex]
    if (!ability || abilityIndex < 0) return false
    const usageKey = `${abilityIndex}:${ability.name}`
    if (evolvedCard.abilityUses?.[usageKey] === state.turnNumber) return false
    const [zoneName, instanceId] = selectedIndices[0].split(':', 2)
    const index = zoneName === 'discard' ? side.discard.findIndex((card) => card.instanceId === instanceId) : -1
    if (index < 0 || normalizeTcgBattleAbilityCardName(side.discard[index].name).replace(/[^a-z0-9]/g, '') !== 'shedinja' || !canTcgBattlePutPokemonOnBench(side, side.discard[index])) return false
    const [card] = side.discard.splice(index, 1)
    const played = createTcgBattleCardState(toTcgBattleCardSummary(card), side.back.length)
    played.subtypes = ['Basic']
    side.back.push(played)
    evolvedCard.abilityUses = { ...evolvedCard.abilityUses, [usageKey]: state.turnNumber }
    state.log.unshift(`${evolvedCard.name}'s Ability put Shedinja from the discard pile onto the Bench as a Basic Pokémon.`)
    return true
  }
  const indices = selectedIndices.map(Number)
  if (indices.some((index) => !Number.isInteger(index) || index < 0 || index >= side.deck.length)) return false
  const cards = indices.map((index) => side.deck[index])
  if (cards.some((card) => namedSearchNames.length
    ? !namedSearchNames.includes(normalizeTcgBattleAbilityCardName(card.name)) || !canTcgBattlePutPokemonOnBench(side, card)
    : shedinjaSearch
    ? normalizeTcgBattleAbilityCardName(card.name) !== 'shedinja' || !canTcgBattlePutPokemonOnBench(side, card)
    : !card.subtypes.some((subtype) => subtype.toLowerCase() === 'basic') || !canTcgBattlePutPokemonOnBench(side, card))) return false
  if (cards.length > getOpenTcgBattleBenchSlots(side)) return false

  for (const index of [...indices].sort((a, b) => b - a)) side.deck.splice(index, 1)
  side.back.push(...cards.map((card, index) => {
    const played = createTcgBattleCardState(card, side.back.length + index)
    if (shedinjaSearch) played.subtypes = ['Basic']
    return played
  }))
  shuffleTcgBattleDeck(side)
  state.log.unshift(`${evolvedCard.name}'s Ability put ${cards.length} Basic Pokémon onto the Bench.`)
  return true
}

function hasTcgBattleMiloticDiscardBenchAbility(card: TcgBattleCardSummary): boolean {
  return normalizeTcgBattleAbilityCardName(card.name) === 'milotic' && Boolean(card.abilities?.some((ability) => normalizeTcgBattleAbilityText(ability.text).replace(/\s+/g, ' ').trim() === 'once during your turn, when you play this pokemon from your hand to evolve 1 of your pokemon, you may use this ability. each player puts a basic pokemon from their discard pile onto their bench. (your opponent puts a basic pokemon onto their bench first.)'))
}

function applyTcgBattleMiloticDiscardBench(state: TcgBattleState, sideKey: TcgBattleSide, evolvedCard: TcgBattleCardState): boolean {
  if (!hasTcgBattleMiloticDiscardBenchAbility(evolvedCard) || isTcgBattleAbilitySuppressedByShadyTail(evolvedCard, [state.player, state.opponent])) return false
  const abilityIndex = evolvedCard.abilities?.findIndex((ability) => hasTcgBattleMiloticDiscardBenchAbility({ ...evolvedCard, abilities: [ability] })) ?? -1
  const ability = evolvedCard.abilities?.[abilityIndex]
  if (!ability || abilityIndex < 0 || evolvedCard.abilityUses?.[`${abilityIndex}:${ability.name}`] === state.turnNumber) return false
  const firstSide: TcgBattleSide = sideKey === 'player' ? 'opponent' : 'player'
  const nextSide: TcgBattleSide = sideKey
  const putBasicOnBench = (ownerKey: TcgBattleSide) => {
    const owner = state[ownerKey]
    if (getOpenTcgBattleBenchSlots(owner) < 1) return undefined
    const index = owner.discard
      .map((card, cardIndex) => ({ card, cardIndex }))
      .filter(({ card }) => card.subtypes.some((subtype) => subtype.toLowerCase() === 'basic') && canTcgBattlePutPokemonOnBench(owner, card))
      .sort((a, b) => b.card.hp - a.card.hp)[0]?.cardIndex
    if (index === undefined) return undefined
    const [card] = owner.discard.splice(index, 1)
    const benched = createTcgBattleCardState(toTcgBattleCardSummary(card), owner.back.length)
    owner.back.push(benched)
    return benched
  }
  const first = putBasicOnBench(firstSide)
  const second = putBasicOnBench(nextSide)
  if (!first && !second) return false
  evolvedCard.abilityUses = { ...evolvedCard.abilityUses, [`${abilityIndex}:${ability.name}`]: state.turnNumber }
  state.log.unshift(`${evolvedCard.name}'s ${ability.name} put ${first ? `${first.name} onto ${firstSide === 'player' ? 'your' : "the opponent's"} Bench` : 'no Basic Pokémon onto the first Bench'} and ${second ? `${second.name} onto ${nextSide === 'player' ? 'your' : "the opponent's"} Bench` : 'no Basic Pokémon onto the second Bench'}.`)
  state.lastAction = { id: randomUUID(), side: sideKey, kind: 'ability', frontId: evolvedCard.instanceId, abilityName: ability.name, abilityIndex, abilityEffect: 'benchSearch' }
  return true
}

function applyTcgBattleEvolutionDrawAbility(state: TcgBattleState, sideKey: TcgBattleSide, evolvedCard: TcgBattleCardState): boolean {
  const count = getTcgBattleEvolutionDrawCount(evolvedCard)
  if (!count || isTcgBattleAbilitySuppressedByShadyTail(evolvedCard, [state.player, state.opponent])) return false
  const thievulAbility = evolvedCard.name.toLowerCase() === 'thievul' && evolvedCard.abilities?.some((ability) => ability.text.replace(/[’]/g, "'").toLowerCase().normalize('NFD').replace(/\p{Diacritic}/gu, '').replace(/\s+/g, ' ').trim() === "when you play this pokemon from your hand to evolve 1 of your pokemon during your turn, you may have each player shuffle their hand and put it on the bottom of their deck. if either player put any cards on the bottom of their deck in this way, each player draws 4 cards.")
  const vaporeonExAbility = normalizeTcgBattleAbilityCardName(evolvedCard.name) === 'vaporeonex' && evolvedCard.abilities?.some((ability) => normalizeTcgBattleAbilityText(ability.text).replace(/\s+/g, ' ').trim() === 'once during your turn, when you play vaporeon ex from your hand to evolve 1 of your pokemon, you may have your opponent shuffle his or her hand into his or her deck. then, your opponent draws up to 4 cards.')
  const alcremieAbility = normalizeTcgBattleAbilityCardName(evolvedCard.name) === 'alcremie' && evolvedCard.abilities?.some((ability) => normalizeTcgBattleAbilityText(ability.text).replace(/\s+/g, ' ').trim() === 'when you play this pokemon from your hand to evolve 1 of your pokemon during your turn, you may have each player draw a card.')
  const side = state[sideKey]
  if (alcremieAbility) {
    const drawCounts = new Map<TcgBattleSide, number>()
    for (const ownerKey of ['player', 'opponent'] as const) {
      const owner = state[ownerKey]
      const drawn = drawTcgBattleCards(owner.deck, 1)
      const drawnIds = new Set(drawn.map((card) => card.id))
      owner.deck = owner.deck.filter((card) => !drawnIds.has(card.id))
      owner.hand.push(...drawn)
      drawCounts.set(ownerKey, drawn.length)
    }
    state.log.unshift(`${evolvedCard.name}'s Ability made each player draw a card (${drawCounts.get('player')} player, ${drawCounts.get('opponent')} opponent).`)
    return true
  }
  if (thievulAbility) {
    const shouldDraw = state.player.hand.length > 0 || state.opponent.hand.length > 0
    for (const owner of [state.player, state.opponent]) {
      const hand = owner.hand.splice(0)
      for (let index = hand.length - 1; index > 0; index -= 1) {
        const swapIndex = randomInt(0, index + 1)
        ;[hand[index], hand[swapIndex]] = [hand[swapIndex], hand[index]]
      }
      owner.deck.push(...hand.map(toTcgBattleCardSummary))
    }
    const drawnBySide: Array<{ side: TcgBattleSide; count: number }> = []
    if (shouldDraw) {
      for (const ownerKey of ['player', 'opponent'] as const) {
        const owner = state[ownerKey]
        const drawn = drawTcgBattleCards(owner.deck, Math.min(4, owner.deck.length))
        const drawnIds = new Set(drawn.map((card) => card.id))
        owner.deck = owner.deck.filter((card) => !drawnIds.has(card.id))
        owner.hand.push(...drawn)
        drawnBySide.push({ side: ownerKey, count: drawn.length })
      }
    }
    state.log.unshift(`${evolvedCard.name}'s Ability shuffled both hands to the bottoms of their owners' decks${shouldDraw ? `; each player drew up to 4 cards (${drawnBySide.map((entry) => `${entry.count} ${entry.side} cards`).join(', ')})` : '; neither hand contained cards, so neither player drew'}.`)
    return true
  }
  if (vaporeonExAbility) {
    const opponent = state[sideKey === 'player' ? 'opponent' : 'player']
    const shuffledCount = opponent.hand.length
    opponent.deck.push(...opponent.hand.splice(0).map(toTcgBattleCardSummary))
    shuffleTcgBattleDeck(opponent)
    const drawn = drawTcgBattleCards(opponent.deck, Math.min(4, opponent.deck.length))
    const drawnIds = new Set(drawn.map((card) => card.id))
    opponent.deck = opponent.deck.filter((card) => !drawnIds.has(card.id))
    opponent.hand.push(...drawn)
    state.log.unshift(`${evolvedCard.name}'s Ability made the opponent shuffle ${shuffledCount} card${shuffledCount === 1 ? '' : 's'} into their deck and draw ${drawn.length} card${drawn.length === 1 ? '' : 's'}.`)
    return true
  }
  const drawn = drawTcgBattleCards(side.deck, Math.min(count, side.deck.length))
  const drawnIds = new Set(drawn.map((card) => card.id))
  side.deck = side.deck.filter((card) => !drawnIds.has(card.id))
  side.hand.push(...drawn)
  state.log.unshift(`${evolvedCard.name}'s Ability drew ${drawn.length} card${drawn.length === 1 ? '' : 's'}.`)
  return true
}

function applyTcgBattleEvolutionAttackBoost(state: TcgBattleState, sideKey: TcgBattleSide, evolvedCard: TcgBattleCardState): boolean {
  const effect = getTcgBattleEvolutionAttackBoost(evolvedCard)
  if (!effect || isTcgBattleAbilitySuppressedByShadyTail(evolvedCard, [state.player, state.opponent])) return false
  state[sideKey].temporaryAttackDamageBoosts = [
    ...(state[sideKey].temporaryAttackDamageBoosts || []),
    { subtype: effect.subtype, damageBonus: effect.damageBonus, targetActiveOnly: effect.targetActiveOnly, turnNumber: state.turnNumber },
  ]
  const ability = evolvedCard.abilities?.find((entry) => getTcgBattleEvolutionAttackBoost({ ...evolvedCard, abilities: [entry] }))
  state.log.unshift(`${evolvedCard.name}'s ${ability?.name || 'Ability'} boosted Basic Pokémon's attacks by ${effect.damageBonus} damage against the opponent's Active Pokémon this turn.`)
  return true
}

function isTcgBattleSlakingLazyBlowAbility(card: TcgBattleCardState, abilityIndex: number) {
  const ability = card.abilities?.[abilityIndex]
  return normalizeTcgBattleAbilityCardName(card.name) === 'slaking' && normalizeTcgBattleAbilityText(ability?.text || '').replace(/\s+/g, ' ').trim() === "once during your turn (before your attack), if slaking is your active pokemon, you may flip a coin. if heads, slaking's lazy blow attack's base damage is 130 during this turn. if tails, slaking can't attack or retreat during this turn. (if slaking is no longer your active pokemon, this effect ends)."
}

function applyTcgBattleSlakingLazyBlow(state: TcgBattleState, sideKey: TcgBattleSide, source: TcgBattleCardState, abilityIndex: number, abilityName: string) {
  const heads = flipTcgBattleCoinForSide(state, state.activeSide) === 'heads'
  if (heads) {
    source.temporaryEffects = {
      ...source.temporaryEffects,
      attackBaseDamageOverrides: [
        ...(source.temporaryEffects?.attackBaseDamageOverrides || []).filter((entry) => entry.attackName.toLowerCase() !== 'lazy blow'),
        { attackName: 'Lazy Blow', baseDamage: 130, turnNumber: state.turnNumber },
      ],
    }
  } else {
    source.temporaryEffects = {
      ...source.temporaryEffects,
      cannotAttack: { remainingTurns: 1 },
      cannotRetreat: { remainingTurns: 1 },
    }
  }
  source.abilityUses = { ...source.abilityUses, [`${abilityIndex}:${abilityName}`]: state.turnNumber }
  state.log.unshift(heads
    ? `${source.name}'s ${abilityName} flipped heads. Lazy Blow's base damage is 130 this turn.`
    : `${source.name}'s ${abilityName} flipped tails. It cannot attack or retreat this turn.`)
  state.lastAction = { id: randomUUID(), side: sideKey, kind: 'ability', frontId: source.instanceId, abilityName, abilityEffect: 'damageBoost' }
  return heads
}

function isTcgBattleBlisseyKindEggAbility(source: TcgBattleCardState, abilityIndex: number) {
  const text = normalizeTcgBattleAbilityText(source.abilities?.[abilityIndex]?.text || '').replace(/\s+/g, ' ').trim()
  return normalizeTcgBattleAbilityCardName(source.name) === 'blissey' && text === "once during your turn (before your attack), if happiny is anywhere under blissey, you may choose a number of cards in your hand up to the amount of energy attached to blissey and put those cards on top of your deck. shuffle your deck afterward. then, draw that many cards. this power can't be used if blissey is affected by a special condition."
}

function applyTcgBattleBlisseyKindEgg(state: TcgBattleState, sideKey: TcgBattleSide, source: TcgBattleCardState, abilityIndex: number, abilityName: string, selectedCardIds: string[]) {
  const side = state[sideKey]
  const selectedCards = selectedCardIds.map((instanceId) => side.hand.find((card) => card.instanceId === instanceId)!)
  const returnedCards = selectedCards.map((card) => {
    const { instanceId: _instanceId, currentHp: _currentHp, ...summary } = card
    return summary
  })
  side.hand = side.hand.filter((card) => !selectedCardIds.includes(card.instanceId))
  side.deck.unshift(...returnedCards)
  shuffleTcgBattleDeck(side)
  const drawn = drawTcgBattleCards(side.deck, selectedCards.length)
  const drawnIds = new Set(drawn.map((card) => card.id))
  side.deck = side.deck.filter((card) => !drawnIds.has(card.id))
  side.hand.push(...drawn.map((card) => createTcgBattleCardState(card, side.hand.length)))
  source.abilityUses = { ...source.abilityUses, [`${abilityIndex}:${abilityName}`]: state.turnNumber }
  state.log.unshift(`${source.name}'s ${abilityName} shuffled ${selectedCards.length} card${selectedCards.length === 1 ? '' : 's'} from hand into the deck, then drew ${drawn.length}. The Energy limit uses the shared Energy pool.`)
  state.lastAction = { id: randomUUID(), side: sideKey, kind: 'ability', frontId: source.instanceId, abilityName, abilityEffect: 'deckSwap' }
}

function applyTcgBattleEvolutionFullHealAbility(state: TcgBattleState, sideKey: TcgBattleSide, evolvedCard: TcgBattleCardState): boolean {
  if (isTcgBattleHealingPreventedForTarget(state, sideKey, evolvedCard) || !hasTcgBattleEvolutionFullHealEffect(evolvedCard) || isTcgBattleAbilitySuppressedByShadyTail(evolvedCard, [state.player, state.opponent])) return false
  evolvedCard.currentHp = evolvedCard.hp
  state.log.unshift(`${evolvedCard.name}'s Ability healed all damage during evolution.`)
  return true
}

function applyTcgBattleEvolutionTargetedFullHealAbility(state: TcgBattleState, sideKey: TcgBattleSide, evolvedCard: TcgBattleCardState, targetId: string): boolean {
  if (!hasTcgBattleEvolutionTargetedFullHealEffect(evolvedCard) || isTcgBattleAbilitySuppressedByShadyTail(evolvedCard, [state.player, state.opponent])) return false
  const side = state[sideKey]
  const isWhimsicott = evolvedCard.name.toLowerCase().replace(/[^a-z0-9]/g, '') === 'whimsicott'
  const isMiloticHealingRipples = evolvedCard.abilities?.some((ability) => normalizeTcgBattleAbilityText(ability.text).replace(/\s+/g, ' ').trim() === 'once during your turn, when you play this pokemon from your hand to evolve 1 of your pokemon, you may heal 60 damage from 1 of your {w} pokemon.')
  const target = [...side.front, ...side.back].find((card) => card.instanceId === targetId && card.currentHp > 0 && card.currentHp < card.hp && (!isWhimsicott || side.front.some((active) => active.instanceId === card.instanceId) && card.types.some((type) => type.toLowerCase() === 'grass')) && (!isMiloticHealingRipples || card.types.some((type) => type.toLowerCase() === 'water')))
  if (!target || isTcgBattleHealingPreventedForTarget(state, sideKey, target)) return false
  target.currentHp = isMiloticHealingRipples ? Math.min(target.hp, target.currentHp + 60) : target.hp
  if (isWhimsicott) side.energy = 0
  const abilityName = evolvedCard.abilities?.find((ability) => hasTcgBattleEvolutionTargetedFullHealEffect({ ...evolvedCard, abilities: [ability] }))?.name || 'Ability'
  state.log.unshift(isMiloticHealingRipples
    ? `${evolvedCard.name}'s ${abilityName} healed 60 damage from ${target.name}.`
    : isWhimsicott
    ? `${evolvedCard.name}'s ${abilityName} healed all damage from ${target.name} and discarded all Energy from the shared pool.`
    : `${evolvedCard.name}'s ${abilityName} healed all damage from ${target.name}.`)
  return true
}

function applyTcgBattleMiloticHealingShower(state: TcgBattleState, sideKey: TcgBattleSide, evolvedCard: TcgBattleCardState): boolean {
  if (isTcgBattleHealingPrevented(state) || !hasTcgBattleEvolutionMassHealEffect(evolvedCard) || isTcgBattleAbilitySuppressedByShadyTail(evolvedCard, [state.player, state.opponent])) return false
  const normalizedName = evolvedCard.name.toLowerCase().replace(/[^a-z0-9]/g, '')
  const isDachsbunEx = normalizedName === 'dachsbunex'
  const isGarchompC = normalizedName === 'garchompclvx'
  const isBlissey = normalizedName === 'blissey' || normalizedName === 'blisseyex'
  let healedCount = 0
  for (const targetSide of (isGarchompC || isDachsbunEx || isBlissey ? [sideKey] : ['player', 'opponent'] as const)) {
    const side = state[targetSide]
    for (const card of [...side.front, ...side.back]) {
      const isPokemonEx = card.subtypes.some((subtype) => subtype.toLowerCase().replace(/[^a-z0-9]/g, '') === 'ex')
      const isPokemonSP = card.subtypes.some((subtype) => subtype.toLowerCase() === 'sp') || card.name.toLowerCase().includes(' sp')
      const isEvolution = Boolean(card.evolutionStack?.length) || card.subtypes.some((subtype) => /^stage [12]$/i.test(subtype))
      if ((!isBlissey && (isDachsbunEx ? !isEvolution : isGarchompC ? !isPokemonSP : isPokemonEx)) || card.currentHp >= card.hp || isTcgBattleHealingPreventedForTarget(state, targetSide, card)) continue
      card.currentHp = card.hp
      healedCount += 1
    }
  }
  if ((isDachsbunEx || isBlissey) && healedCount > 0) state[sideKey].energy = 0
  state.log.unshift(isDachsbunEx
    ? `${evolvedCard.name}'s Ability healed ${healedCount} of your Evolution Pokémon${healedCount > 0 ? ' and discarded all Energy from the shared pool' : ''}.`
    : isBlissey ? `${evolvedCard.name}'s Ability healed all damage from ${healedCount} of your Pokémon${healedCount > 0 ? ' and discarded all Energy from the shared pool' : ''}.`
    : isGarchompC ? `${evolvedCard.name}'s Healing Breath healed ${healedCount} of your Pokémon SP.` : `${evolvedCard.name}'s Healing Shower healed ${healedCount} Pokémon.`)
  return true
}

function applyTcgBattleEvolutionSwitchAbility(state: TcgBattleState, sideKey: TcgBattleSide, evolvedCard: TcgBattleCardState, benchId: string): boolean {
  if (!hasTcgBattleEvolutionSwitchEffect(evolvedCard) || isTcgBattleAbilitySuppressedByShadyTail(evolvedCard, [state.player, state.opponent])) return false
  const opponentSideKey = sideKey === 'player' ? 'opponent' : 'player'
  const opponent = state[opponentSideKey]
  const active = opponent.front[0]
  const maxRemainingHp = getTcgBattleEvolutionSwitchMaxRemainingHp(evolvedCard)
  const benchTarget = opponent.back.find((card) => card.instanceId === benchId && card.currentHp > 0 && (!hasTcgBattleEvolutionOnlySwitchEffect(evolvedCard) || Boolean(card.evolvesFrom)) && (maxRemainingHp === undefined || card.currentHp <= maxRemainingHp) && (!hasTcgBattleEvolutionExSwitchEffect(evolvedCard) || card.subtypes.some((subtype) => ['ex', 'pokemon-ex'].includes(subtype.toLowerCase()))))
  if (!active || !benchTarget) return false
  const switched = swapTcgBattleCards(state, opponentSideKey, active, benchTarget.instanceId, true)
  if (switched) state.log.unshift(`${evolvedCard.name}'s Ability switched ${benchTarget.name} into the opposing Active Spot.`)
  return switched
}

function applyTcgBattleEvolutionReturnPokemon(state: TcgBattleState, sideKey: TcgBattleSide, evolvedCard: TcgBattleCardState, targetId: string): boolean {
  if (!hasTcgBattleEvolutionReturnPokemonEffect(evolvedCard) || isTcgBattleAbilitySuppressedByShadyTail(evolvedCard, [state.player, state.opponent])) return false
  const side = state[sideKey]
  const target = [...side.front, ...side.back].find((card) => card.instanceId === targetId && card.currentHp > 0 && !normalizeTcgBattleAbilityCardName(card.name).startsWith('corviknight'))
  if (!target) return false
  const isActive = side.front.some((card) => card.instanceId === target.instanceId)
  if (isActive && !side.back.some((card) => card.currentHp > 0)) return false
  const returned = [...(target.evolutionStack || []), toTcgBattleCardSummary(target)]
  side.front = side.front.filter((card) => card.instanceId !== targetId)
  side.back = side.back.filter((card) => card.instanceId !== targetId)
  side.hand.push(...returned.map((card, index) => createTcgBattleCardState(card, side.hand.length + index)))
  compactTcgBattleBoard(side)
  if (isActive) {
    if (sideKey === 'opponent') promoteOpponentIfNeeded(state)
    else {
      state.pendingPromotion = sideKey
      state.resumeSideAfterPromotion = sideKey
      state.resumeTurnAfterPromotion = true
      state.phase = 'promotion'
    }
  }
  state.log.unshift(`${evolvedCard.name}'s Ability returned ${target.name}${target.evolutionStack?.length ? ' and its Evolution cards' : ''} to the hand. Individual attached cards are not tracked by this battle format.`)
  return true
}

function applyTcgBattleEvolutionCardSearch(state: TcgBattleState, sideKey: TcgBattleSide, evolvedCard: TcgBattleCardState, deckIndex: number): boolean {
  if (!hasTcgBattleEvolutionCardSearchEffect(evolvedCard) || isTcgBattleAbilitySuppressedByShadyTail(evolvedCard, [state.player, state.opponent])) return false
  const side = state[sideKey]
  if (!Number.isInteger(deckIndex) || deckIndex < 0 || deckIndex >= side.deck.length) return false
  const [card] = side.deck.splice(deckIndex, 1)
  side.hand.push(createTcgBattleCardState(card, side.hand.length))
  shuffleTcgBattleDeck(side)
  state.log.unshift(`${evolvedCard.name}'s Ability searched for ${card.name} and shuffled the deck.`)
  return true
}

function applyTcgBattleEvolutionSelfSwitchAbility(state: TcgBattleState, sideKey: TcgBattleSide, evolvedCard: TcgBattleCardState, activeId: string): boolean {
  if (!hasTcgBattleEvolutionSelfSwitchEffect(evolvedCard) || isTcgBattleAbilitySuppressedByShadyTail(evolvedCard, [state.player, state.opponent])) return false
  const side = state[sideKey]
  const active = side.front.find((card) => card.instanceId === activeId && card.currentHp > 0)
  const evolvedIndex = side.back.findIndex((card) => card.instanceId === evolvedCard.instanceId && card.currentHp > 0)
  if (!active || evolvedIndex < 0) return false
  const switched = swapTcgBattleCards(state, sideKey, active, evolvedCard.instanceId)
  if (switched) state.log.unshift(`${evolvedCard.name}'s Flame Dash switched it with ${active.name}. Individual attached Energy cannot be moved in this battle format.`)
  return switched
}

function applyTcgBattleLightMachampTagTeam(state: TcgBattleState, sideKey: TcgBattleSide, evolvedCard: TcgBattleCardState): boolean {
  if (normalizeTcgBattleAbilityCardName(evolvedCard.name) !== 'lightmachamp' || isTcgBattleAbilitySuppressedByShadyTail(evolvedCard, [state.player, state.opponent])) return false
  const hasTagTeam = (evolvedCard.abilities || []).some((ability) => {
    const text = ability.text.replace(/[’]/g, "'").toLowerCase().normalize('NFD').replace(/\p{Diacritic}/gu, '').replace(/pokémon/g, 'pokemon').replace(/\s+/g, ' ').trim()
    return text === "when you play light machamp from your hand, if is on your bench, remove 3 damage counters than that, remove all of them. then, switch light machamp with your active pokemon." ||
      text === "when you play light machamp from your hand, if it is on your bench, remove 3 damage counters from your active pokemon. if it has fewer damage counters than that, remove all of them. then, switch light machamp with your active pokemon."
  })
  const side = state[sideKey]
  const active = side.front[0]
  if (!hasTagTeam || !active || !side.back.some((card) => card.instanceId === evolvedCard.instanceId && card.currentHp > 0)) return false
  const healed = isTcgBattleHealingPreventedForTarget(state, sideKey, active) ? 0 : Math.min(30, active.hp - active.currentHp)
  active.currentHp += healed
  const switched = swapTcgBattleCards(state, sideKey, active, evolvedCard.instanceId)
  state.log.unshift(`${evolvedCard.name}'s Tag Team ${healed > 0 ? `healed ${active.name} for ${healed} damage and ` : ''}${switched ? 'switched into the Active Spot' : 'could not switch into the Active Spot'}.`)
  return true
}

function useOpponentPokemonSwapPower(state: TcgBattleState): boolean {
  for (const source of [...state.opponent.front, ...state.opponent.back].filter((card) => card.currentHp > 0)) {
    if (isTcgBattleAbilitySuppressedByShadyTail(source, [state.player, state.opponent])) continue
    for (const [abilityIndex, ability] of (source.abilities || []).entries()) {
      const power = getTcgBattlePokemonSwapPower(ability.text)
      if (!power) continue
      const usageKey = power.sharedUse === false ? `${abilityIndex}:${ability.name}` : `shared:${power.powerName}`
      if (power.sharedUse !== false && [...state.opponent.front, ...state.opponent.back].some((card) => card.abilityUses?.[usageKey] === state.turnNumber) || source.abilityUses?.[usageKey] === state.turnNumber) continue
      const normalizeName = (value: string) => value.toLowerCase().normalize('NFD').replace(/\p{Diacritic}/gu, '').replace(/[^a-z0-9]/g, '')
      if (!normalizeName(source.name).includes(normalizeName(power.pokemonName))) continue
      if (power.sourceName ? normalizeName(source.name) !== normalizeName(power.sourceName) : !normalizeName(source.name).includes(normalizeName(power.pokemonName))) continue
      if (power.activeOnly && !state.opponent.front.some((card) => card.instanceId === source.instanceId) || power.firstTurnOnly && state.turnNumber !== 1) continue
      const inheritedDamage = Math.max(0, source.hp - source.currentHp)
      const replacementZone = power.replacementZone || 'deck'
      const replacementPool = state.opponent[replacementZone]
      const replacement = replacementPool.find((card) => card.hp > inheritedDamage && (power.allowedNames ? power.allowedNames.some((name) => normalizeName(name) === normalizeName(card.name)) : normalizeName(card.name).includes(normalizeName(power.pokemonName))) && !power.excludedNames?.some((name) => normalizeName(name) === normalizeName(card.name)) && (!power.basicOnly || card.subtypes.some((subtype) => normalizeName(subtype) === 'basic')) && (!power.pokemonVOnly || card.subtypes.some((subtype) => ['v', 'pokemonv'].includes(normalizeName(subtype)))) && (!power.excludePokemonEx || !card.subtypes.some((subtype) => ['ex', 'pokemonex'].includes(normalizeName(subtype)))))
      if (!replacement) continue
      if (!useTcgBattlePokemonSwapPower(state, 'opponent', source.instanceId, abilityIndex, replacement.id)) return true
    }
  }
  return false
}

function useOpponentMetagrossMagneticReversal(state: TcgBattleState): boolean {
  const textExpected = "once during your turn (before your attack), you may flip a coin. if heads, switch 1 of your opponent's benched pokemon with 1 of the defending pokemon. this power can't be used if metagross is affected by a special condition."
  const activeTarget = state.player.front.filter((card) => card.currentHp > 0).sort((a, b) => a.currentHp - b.currentHp)[0]
  const benchTarget = state.player.back.filter((card) => card.currentHp > 0).sort((a, b) => b.currentHp - a.currentHp)[0]
  if (!activeTarget || !benchTarget) return false
  for (const source of [...state.opponent.front, ...state.opponent.back].filter((card) => card.currentHp > 0 && !card.statusConditions?.length && !isTcgBattleAbilitySuppressedByShadyTail(card, [state.player, state.opponent]))) {
    if (source.name.replace(/[^a-z0-9]/gi, '').toLowerCase() !== 'metagross') continue
    for (const [abilityIndex, ability] of (source.abilities || []).entries()) {
      const text = ability.text.replace(/[’]/g, "'").toLowerCase().normalize('NFD').replace(/\p{Diacritic}/gu, '').replace(/\s+/g, ' ').trim()
      if (text !== textExpected) continue
      const usageKey = `${abilityIndex}:${ability.name}`
      if (source.abilityUses?.[usageKey] === state.turnNumber) continue
      const result = flipTcgBattleCoinForSide(state, state.activeSide)
      recordCoinFlipEvent(state, { sourceId: source.instanceId, side: 'opponent', results: [result], heads: result === 'heads' ? 1 : 0, tails: result === 'tails' ? 1 : 0, purpose: 'effect' })
      if (result === 'heads' && !swapTcgBattleCards(state, 'player', activeTarget, benchTarget.instanceId, true)) continue
      source.abilityUses = { ...source.abilityUses, [usageKey]: state.turnNumber }
      state.log.unshift(`Opponent used Metagross's Magnetic Reversal and flipped ${result}${result === 'heads' ? `, switching ${benchTarget.name} with ${activeTarget.name}` : ''}.`)
      state.lastAction = { id: randomUUID(), side: 'opponent', kind: 'ability', frontId: source.instanceId, ...(result === 'heads' ? { targetId: benchTarget.instanceId } : {}), abilityName: ability.name, abilityEffect: 'switch' }
      return true
    }
  }
  return false
}

function useOpponentBenchSearchAbility(state: TcgBattleState): boolean {
  const energyTypeNames: Record<string, string> = { g: 'grass', r: 'fire', w: 'water', l: 'lightning', p: 'psychic', m: 'fighting', d: 'darkness', y: 'metal', c: 'colorless', f: 'fairy' }
  for (const source of [...state.opponent.front, ...state.opponent.back].filter((card) => card.currentHp > 0 && !isTcgBattleAbilitySuppressedByShadyTail(card, [state.player, state.opponent]))) {
    for (const [abilityIndex, ability] of (source.abilities || []).entries()) {
      const text = ability.text.replace(/[’]/g, "'").toLowerCase().normalize('NFD').replace(/\p{Diacritic}/gu, '').replace(/\s+/g, ' ').trim()
      const match = text.match(/^once during your turn, you may search your deck for up to (\d+) basic \{([grwlpmdycf])\} pokemon and put them onto your bench\. then, shuffle your deck\.$/)
      if (!match) continue
      const usageKey = `${abilityIndex}:${ability.name}`
      if (source.abilityUses?.[usageKey] === state.turnNumber) continue
      const type = energyTypeNames[match[2]]
      const capacity = Math.min(Number(match[1]), getOpenTcgBattleBenchSlots(state.opponent))
      const indices = state.opponent.deck.map((card, index) => ({ card, index })).filter(({ card }) => card.subtypes.includes('Basic') && card.types.some((cardType) => cardType.toLowerCase() === type) && canTcgBattlePutPokemonOnBench(state.opponent, card)).slice(0, capacity).map(({ index }) => index)
      if (!indices.length) continue
      const selected = [...indices].sort((a, b) => b - a).map((index) => state.opponent.deck.splice(index, 1)[0]).reverse()
      state.opponent.back.push(...selected.map((card, index) => createTcgBattleCardState(card, state.opponent.back.length + index)))
      source.abilityUses = { ...source.abilityUses, [usageKey]: state.turnNumber }
      shuffleTcgBattleDeck(state.opponent)
      state.log.unshift(`Opponent used ${source.name}'s ${ability.name} to put ${selected.length} Pokémon on the Bench.`)
      state.lastAction = { id: randomUUID(), side: 'opponent', kind: 'ability', frontId: source.instanceId, abilityName: ability.name, abilityEffect: 'benchSearch' }
      return true
    }
  }
  return false
}

function useOpponentKabutoReviveFriends(state: TcgBattleState): boolean {
  const side = state.opponent
  for (const source of [...side.front, ...side.back].filter((card) => card.currentHp > 0 && !isTcgBattleAbilitySuppressedByShadyTail(card, [state.player, side]))) {
    const abilityIndex = source.abilities?.findIndex((entry) => isTcgBattleKabutoReviveFriends(source.name, entry.text)) ?? -1
    const ability = source.abilities?.[abilityIndex]
    const usageKey = `${abilityIndex}:${ability?.name || ''}`
    if (!ability || source.statusConditions?.some((status) => ['asleep', 'confused', 'paralyzed'].includes(status)) || source.abilityUses?.[usageKey] === state.turnNumber || getOpenTcgBattleBenchSlots(side) < 1) continue
    const deckIndex = side.deck.findIndex((card) => card.name.toLowerCase() === 'kabuto' && canTcgBattlePutPokemonOnBench(side, card))
    if (deckIndex < 0) continue
    const result = flipTcgBattleCoinForSide(state, state.activeSide)
    recordCoinFlipEvent(state, { sourceId: source.instanceId, side: 'opponent', results: [result], heads: result === 'heads' ? 1 : 0, tails: result === 'tails' ? 1 : 0, purpose: 'effect' })
    source.abilityUses = { ...source.abilityUses, [usageKey]: state.turnNumber }
    if (result === 'heads') {
      const [searched] = side.deck.splice(deckIndex, 1)
      const played = createTcgBattleCardState(searched, side.back.length + side.hand.length + side.discard.length)
      played.subtypes = [...new Set([...played.subtypes, 'Basic'])]
      played.playedToBenchTurn = state.turnNumber
      side.back.push(played)
      shuffleTcgBattleDeck(side)
      state.log.unshift(`Opponent used ${source.name}'s ${ability.name}, flipped heads, and put Kabuto onto the Bench as a Basic Pokémon.`)
    } else {
      state.log.unshift(`Opponent used ${source.name}'s ${ability.name} and flipped tails.`)
    }
    state.lastAction = { id: randomUUID(), side: 'opponent', kind: 'ability', frontId: source.instanceId, targetId: result === 'heads' ? side.back.at(-1)?.instanceId : undefined, abilityName: ability.name, abilityEffect: 'benchSearch' }
    return true
  }
  return false
}

