function useOpponentIgglybuffGaze(state: TcgBattleState): boolean {
  const side = state.opponent
  const powerTargets = state.player.back.filter((card) => card.currentHp > 0 && hasOnlyTcgBattlePokemonPower(card))
  for (const source of [...side.front, ...side.back].filter((card) => card.currentHp > 0 && !isTcgBattleAbilitySuppressedByShadyTail(card, [state.player, side]))) {
    const abilityIndex = source.abilities?.findIndex((entry) => isTcgBattleIgglybuffGaze(source.name, entry.text) || isTcgBattleGardevoirImprison(source.name, entry.text)) ?? -1
    const ability = source.abilities?.[abilityIndex]
    if (!ability || source.abilityUses?.[`${abilityIndex}:${ability.name}`] === state.turnNumber) continue
    const imprison = isTcgBattleGardevoirImprison(source.name, ability.text)
    if (imprison && (!side.front.some((card) => card.instanceId === source.instanceId) || source.statusConditions?.length)) continue
    const targets = imprison ? [...state.player.front, ...state.player.back].filter((card) => card.currentHp > 0 && card.abilities?.length && !card.temporaryEffects?.imprisonMarker) : powerTargets
    const target = imprison ? targets.sort((a, b) => (b.abilities?.length || 0) - (a.abilities?.length || 0))[0] : targets[0]
    if (!target) continue
    target.temporaryEffects = imprison ? { ...target.temporaryEffects, imprisonMarker: true } : { ...target.temporaryEffects, pokemonPowerSuppression: { remainingTurns: 1 } }
    source.abilityUses = { ...source.abilityUses, [`${abilityIndex}:${ability.name}`]: state.turnNumber }
    state.log.unshift(imprison ? `Opponent used ${source.name}'s ${ability.name} to put an Imprison marker on ${target.name}.` : `Opponent used ${source.name}'s ${ability.name} to stop ${target.name}'s Pokémon Power until the end of its turn.`)
    state.lastAction = { id: randomUUID(), side: 'opponent', kind: 'ability', frontId: source.instanceId, targetId: target.instanceId, abilityName: ability.name, abilityEffect: 'abilitySuppression' }
    return true
  }
  return false
}

function useOpponentIgglybuffDreamDance(state: TcgBattleState): boolean {
  const target = state.player.front.find((card) => card.currentHp > 0)
  if (!target) return false
  for (const source of [...state.opponent.front, ...state.opponent.back].filter((card) => card.currentHp > 0 && !isTcgBattleAbilitySuppressedByShadyTail(card, [state.opponent, state.player]))) {
    const abilityIndex = source.abilities?.findIndex((ability) => normalizeTcgBattleAbilityCardName(source.name) === 'igglybuff' && getTcgBattleCoinFlipStatusPower(ability.text) === 'asleep' && ability.text.toLowerCase().includes('if you use this ability, your turn ends')) ?? -1
    const ability = source.abilities?.[abilityIndex]
    if (!ability || source.abilityUses?.[`${abilityIndex}:${ability.name}`] === state.turnNumber) continue
    const result = flipTcgBattleCoinForSide(state, state.activeSide)
    recordCoinFlipEvent(state, { sourceId: source.instanceId, side: 'opponent', results: [result], heads: result === 'heads' ? 1 : 0, tails: result === 'tails' ? 1 : 0, purpose: 'effect' })
    const events = result === 'heads' ? applyTcgBattleStatusConditions(state, 'opponent', source.instanceId, target.instanceId, [{ target: 'opponent', statuses: ['asleep'] }], true) : []
    state.lastStatusEvents = events.map((event) => ({ ...event, id: randomUUID() }))
    source.abilityUses = { ...source.abilityUses, [`${abilityIndex}:${ability.name}`]: state.turnNumber }
    state.log.unshift(`Opponent used ${source.name}'s ${ability.name}, flipped ${result}${events.length ? `, and put ${target.name} to sleep` : ''}. The Ability ends the turn.`)
    state.lastAction = { id: randomUUID(), side: 'opponent', kind: 'ability', frontId: source.instanceId, ...(events.length ? { targetId: target.instanceId } : {}), abilityName: ability.name, abilityEffect: 'status', abilityStatus: 'asleep' }
    return true
  }
  return false
}

function useOpponentElekidPlayfulPunch(state: TcgBattleState): boolean {
  const side = state.opponent
  const targetSide = state.player
  const target = targetSide.front.find((card) => card.currentHp > 0)
  if (!target) return false
  for (const source of [...side.front, ...side.back].filter((card) => card.currentHp > 0 && !card.statusConditions?.some((status) => ['asleep', 'confused', 'paralyzed'].includes(status)) && !isTcgBattleAbilitySuppressedByShadyTail(card, [side, targetSide]))) {
    const abilityIndex = source.abilities?.findIndex((entry) => isTcgBattleElekidPlayfulPunch(source.name, entry.text)) ?? -1
    const ability = source.abilities?.[abilityIndex]
    const usageKey = `${abilityIndex}:${ability?.name || ''}`
    if (!ability || source.abilityUses?.[usageKey] === state.turnNumber) continue
    const result = flipTcgBattleCoinForSide(state, state.activeSide)
    recordCoinFlipEvent(state, { sourceId: source.instanceId, side: 'opponent', results: [result], heads: result === 'heads' ? 1 : 0, tails: result === 'tails' ? 1 : 0, purpose: 'effect' })
    let damage = 0
    if (result === 'heads') {
      damage = applyTcgWeaknessAndResistance(source, target, 20, { targetIsActive: true, state, targetSide: 'player' })
      target.currentHp -= damage
      recordDamageEvent(state, { sourceId: source.instanceId, targetId: target.instanceId, targetSide: 'player', damage, reason: 'ability' })
    }
    source.abilityUses = { ...source.abilityUses, [usageKey]: state.turnNumber }
    state.log.unshift(`Opponent used ${source.name}'s ${ability.name}, flipped ${result}${result === 'heads' ? `, and did ${damage} damage to ${target.name}` : ''}.`)
    state.lastAction = { id: randomUUID(), side: 'opponent', kind: 'ability', frontId: source.instanceId, targetId: result === 'heads' ? target.instanceId : undefined, abilityName: ability.name, abilityEffect: 'directDamage' }
    return true
  }
  return false
}

