function useOpponentHisuianTyphlosionHex(state: TcgBattleState): boolean {
  const text = "you must discard a psychic energy card from your hand in order to use this ability. once during your turn, you may make your opponent's active pokemon burned and confused."
  const target = state.player.front.find((card) => card.currentHp > 0 && (!card.statusConditions?.includes('burned') || !card.statusConditions?.includes('confused')))
  if (!target) return false
  for (const source of [...state.opponent.front, ...state.opponent.back].filter((card) => card.currentHp > 0 && !isTcgBattleAbilitySuppressedByShadyTail(card, [state.opponent, state.player]))) {
    for (const [abilityIndex, ability] of (source.abilities || []).entries()) {
      const abilityText = ability.text.replace(/[’]/g, "'").toLowerCase().normalize('NFD').replace(/\p{Diacritic}/gu, '').replace(/pokémon/g, 'pokemon').replace(/\s+/g, ' ').trim()
      if (source.name.toLowerCase() !== 'hisuian typhlosion' || abilityText !== text || source.abilityUses?.[`${abilityIndex}:${ability.name}`] === state.turnNumber) continue
      const energyIndex = state.opponent.hand.findIndex((card) => card.name.toLowerCase().includes('psychic energy'))
      if (energyIndex < 0) continue
      const [energy] = state.opponent.hand.splice(energyIndex, 1)
      state.opponent.discard.push(energy)
      const events = applyTcgBattleStatusConditions(state, 'opponent', source.instanceId, target.instanceId, [{ target: 'opponent', statuses: ['burned', 'confused'] }], true)
      if (!events.length) {
        state.opponent.hand.splice(energyIndex, 0, energy)
        state.opponent.discard = state.opponent.discard.filter((card) => card.instanceId !== energy.instanceId)
        continue
      }
      state.lastStatusEvents = events.map((event) => ({ ...event, id: randomUUID() }))
      source.abilityUses = { ...source.abilityUses, [`${abilityIndex}:${ability.name}`]: state.turnNumber }
      state.log.unshift(`Opponent discarded a Psychic Energy for Hisuian Typhlosion's ${ability.name}, Burning and Confusing ${target.name}.`)
      state.lastAction = { id: randomUUID(), side: 'opponent', kind: 'ability', frontId: source.instanceId, targetId: target.instanceId, abilityName: ability.name, abilityEffect: 'status', abilityStatus: 'burned' }
      return true
    }
  }
  return false
}

