function useOpponentXatuPsychicShift(state: TcgBattleState): boolean {
  const recipient = state.player.front.find((card) => card.currentHp > 0)
  if (!recipient) return false
  const sourceSide = state.opponent
  const statuses: TcgBattleStatusCondition[] = ['asleep', 'burned', 'confused', 'paralyzed', 'poisoned']
  for (const source of sourceSide.back.filter((card) => card.currentHp > 0 && !isTcgBattleAbilitySuppressedByShadyTail(card, [sourceSide, state.player]))) {
    for (const [abilityIndex, ability] of (source.abilities || []).entries()) {
      const usageKey = `${abilityIndex}:${ability.name}`
      if (!isTcgBattleXatuPsychicShift(ability.text) || source.name.toLowerCase() !== 'xatu' || source.abilityUses?.[usageKey] === state.turnNumber) continue
      const transferSource = sourceSide.front.find((card) => card.currentHp > 0 && statuses.some((status) => card.statusConditions?.includes(status)))
      const status = statuses.find((candidate) => transferSource?.statusConditions?.includes(candidate))
      if (!transferSource || !status) continue
      transferSource.statusConditions = (transferSource.statusConditions || []).filter((condition) => condition !== status)
      const events = applyTcgBattleStatusConditions(state, 'opponent', source.instanceId, recipient.instanceId, [{ target: 'opponent', statuses: [status] }], true)
      state.lastStatusEvents = events.map((event) => ({ ...event, id: randomUUID() }))
      source.abilityUses = { ...source.abilityUses, [usageKey]: state.turnNumber }
      state.log.unshift(`Opponent used Xatu's ${ability.name} to transfer ${status} from ${transferSource.name} to ${recipient.name}.`)
      state.lastAction = { id: randomUUID(), side: 'opponent', kind: 'ability', frontId: source.instanceId, targetId: recipient.instanceId, abilityName: ability.name, abilityEffect: 'status', abilityStatus: status }
      return true
    }
  }
  return false
}

