      applyTcgBattleEvolutionaryGas(state, 'opponent', evolved.target)
      applyTcgBattleDarkestImpulse(state, 'opponent', evolved.target)
      applyTcgBattleServineSerpentineStrangle(state, 'opponent', evolved.target)
      applyTcgBattleEvolutionStatusEffect(state, 'opponent', evolved.target)
      applyTcgBattleEvolutionAttackProtection(state, evolved.target)
      applyTcgBattleEvolutionDevolution(state, 'opponent', evolved.target)
