function resolveTcgBattleTentacoolCowardice(state: TcgBattleState, sideKey: TcgBattleSide, sourceId: string, abilityIndex: number): string | undefined {
  const side = state[sideKey]
  const source = [...side.front, ...side.back].find((card) => card.instanceId === sourceId && card.currentHp > 0)
  const ability = source?.abilities?.[abilityIndex]
  const isTentacool = normalizeTcgBattleAbilityCardName(source?.name || '') === 'tentacool' && Boolean(ability && isTcgBattleTentacoolCowardice(ability.text))
  const isLopunny = normalizeTcgBattleAbilityCardName(source?.name || '') === 'lopunny' && Boolean(ability && isTcgBattleLopunnyBigJump(ability.text))
  if (state.phase !== 'battle' || state.activeSide !== sideKey || !source || !ability || (!isTentacool && !isLopunny)) return 'This Pokémon cannot use its return Ability right now.'
  if (isTentacool && (source.playedToBenchTurn === state.turnNumber || source.playedToFrontTurn === state.turnNumber)) return 'Tentacool cannot use Cowardice the turn it entered play.'
  if (isTentacool && source.statusConditions?.some((status) => ['asleep', 'confused', 'paralyzed'].includes(status))) return 'Tentacool cannot use Cowardice while Asleep, Confused, or Paralyzed.'
  const usageKey = `${abilityIndex}:${ability.name}`
  if (isLopunny && source.abilityUses?.[usageKey] === state.turnNumber) return 'Lopunny has already used Big Jump this turn.'
  if (isTcgBattleAbilitySuppressedByShadyTail(source, [state.player, state.opponent])) return 'This Pokémon has no usable Abilities while an opposing Ability suppresses it.'
  if (side.front.some((card) => card.instanceId === sourceId) && ![...side.front, ...side.back].some((card) => card.instanceId !== sourceId && card.currentHp > 0)) return 'It cannot return to hand while it is your last Pokémon in play.'
  if (isLopunny) source.abilityUses = { ...source.abilityUses, [usageKey]: state.turnNumber }
  const returnedCards = [...(source.evolutionStack || []), toTcgBattleCardSummary(source)]
  side.front = side.front.filter((card) => card.instanceId !== sourceId)
  side.back = side.back.filter((card) => card.instanceId !== sourceId)
  side.hand.push(...returnedCards.map((card, index) => createTcgBattleCardState(card, side.hand.length + index)))
  compactTcgBattleBoard(side)
  if (side.front.length < 3 && side.back.length > 0) {
    if (sideKey === 'opponent') promoteOpponentIfNeeded(state)
    else {
      state.pendingPromotion = sideKey
      state.phase = 'promotion'
    }
  }
  state.consecutivePasses = 0
  state.log.unshift(`${source.name}'s ${ability.name} returned it${source.evolutionStack?.length ? ' and its Evolution cards' : ''} to the hand. Individual attached Energy is not tracked by this battle format.`)
  state.lastAction = { id: randomUUID(), side: sideKey, kind: 'ability', frontId: sourceId, targetId: sourceId, abilityName: ability.name, abilityEffect: 'handReturn' }
  return undefined
}

