function resolveTcgBattleUnownVanish(state: TcgBattleState, sideKey: TcgBattleSide, sourceId: string, targetId: string): string | undefined {
  const side = state[sideKey]
  const source = [...side.front, ...side.back].find((card) => card.instanceId === sourceId && card.currentHp > 0)
  const abilityIndex = source?.abilities?.findIndex((ability) => isTcgBattleUnownVanish(source.name, ability.text)) ?? -1
  const ability = source?.abilities?.[abilityIndex]
  if (state.phase !== 'battle' || state.activeSide !== sideKey || !source || abilityIndex < 0 || !ability || state.lastAction?.kind !== 'bench' || state.lastAction.side !== sideKey || state.lastAction.frontId !== sourceId) return 'Unown V can only use Vanish when it is played from your hand.'
  const target = [...side.front, ...side.back].find((card) => card.instanceId === targetId && card.currentHp > 0)
  if (!target || target.instanceId === source.instanceId || !target.name.toLowerCase().includes('unown')) return 'Choose another living Pokémon with Unown in its name.'

  const result = flipTcgBattleCoinForSide(state, state.activeSide)
  recordCoinFlipEvent(state, { sourceId, side: sideKey, results: [result], heads: result === 'heads' ? 1 : 0, tails: result === 'tails' ? 1 : 0, purpose: 'effect' })
  if (result === 'heads') {
    const returnedCards = [...(target.evolutionStack || []), toTcgBattleCardSummary(target)]
    side.hand.push(...returnedCards.map((card, index) => createTcgBattleCardState(card, side.hand.length + index)))
    side.front = side.front.filter((card) => card.instanceId !== targetId)
    side.back = side.back.filter((card) => card.instanceId !== targetId)
    compactTcgBattleBoard(side)
  }
  state.log.unshift(result === 'heads'
    ? `${source.name}'s ${ability.name} flipped heads and returned ${target.name}${target.evolutionStack?.length ? ' and its Evolution cards' : ''} to the hand. Individual attached Energy is not tracked by this battle format.`
    : `${source.name}'s ${ability.name} flipped tails. ${target.name} stayed in play.`)
  state.lastAction = { id: randomUUID(), side: sideKey, kind: 'ability', frontId: sourceId, targetId, abilityName: ability.name, abilityEffect: 'handReturn' }
  return undefined
}

