function resolveTcgBattleUnownUndo(state: TcgBattleState, sideKey: TcgBattleSide, sourceId: string, targetId: string): string | undefined {
  const side = state[sideKey]
  const source = side.back.find((card) => card.instanceId === sourceId && card.currentHp > 0)
  const abilityIndex = source?.abilities?.findIndex((ability) =>
    normalizeTcgBattleAbilityCardName(source.name) === 'unownu' &&
    ability.text.replace(/[’]/g, "'").toLowerCase().normalize('NFD').replace(/\p{Diacritic}/gu, '').replace(/pokémon/g, 'pokemon').replace(/\s+/g, ' ').trim() ===
    "once during your turn (before you attack), if you have unown [u], unown [n], unown [d], and unown [o] on your bench, you may return your active pokemon and all cards attached to it to your hand."
  ) ?? -1
  const ability = source?.abilities?.[abilityIndex]
  if (state.phase !== 'battle' || state.activeSide !== sideKey || !source || !ability || abilityIndex < 0) return 'Unown U can only use Undo during its owner’s turn from the Bench.'
  if (isTcgBattleAbilitySuppressedByShadyTail(source, [state.player, state.opponent])) return 'Unown U has no usable Abilities while an opposing Ability suppresses it.'
  if (!['u', 'n', 'd', 'o'].every((letter) => side.back.some((card) => card.currentHp > 0 && normalizeTcgBattleAbilityCardName(card.name) === `unown${letter}`))) return 'Unown U, N, D, and O must all be on your Bench to use Undo.'
  if (source.abilityUses?.[`${abilityIndex}:${ability.name}`] === state.turnNumber) return 'Unown U has already used Undo this turn.'
  const target = side.front.find((card) => card.instanceId === targetId && card.currentHp > 0)
  if (!target || side.back.length === 0) return 'Choose your Active Pokémon; another Pokémon must be available on the Bench.'
  const returned = [...(target.evolutionStack || []), toTcgBattleCardSummary(target)]
  side.hand.push(...returned.map((card, index) => createTcgBattleCardState(card, side.hand.length + index)))
  side.front = side.front.filter((card) => card.instanceId !== targetId)
  compactTcgBattleBoard(side)
  source.abilityUses = { ...source.abilityUses, [`${abilityIndex}:${ability.name}`]: state.turnNumber }
  state.pendingPromotion = sideKey
  state.resumeSideAfterPromotion = sideKey
  state.resumeTurnAfterPromotion = true
  state.phase = 'promotion'
  state.consecutivePasses = 0
  state.log.unshift(`${source.name}'s ${ability.name} returned ${target.name}${target.evolutionStack?.length ? ' and its Evolution cards' : ''} to the hand. Individual attached Energy is not tracked by this battle format.`)
  state.lastAction = { id: randomUUID(), side: sideKey, kind: 'ability', frontId: sourceId, targetId, abilityName: ability.name, abilityEffect: 'handReturn' }
  return undefined
}

