      if (source && isTcgBattleAbilitySuppressedByShadyTail(source, [state.player, state.opponent])) return { success: false, error: 'This Pokémon has no usable Abilities while an opposing Ability suppresses it.' }
      const ability = source?.abilities?.[abilityIndex]
