        const discarded = result === 'heads' && state.opponent.hand.length ? state.opponent.hand.splice(randomInt(0, state.opponent.hand.length), 1)[0] : undefined
        if (discarded) state.opponent.discard.push(discarded)
        source.abilityUses = { ...source.abilityUses, [`${abilityIndex}:${ability.name}`]: state.turnNumber }
        state.log.unshift(`You used Talonflame's Sky Hunt and flipped ${result}${discarded ? `, discarding ${discarded.name} from your opponent's hand` : result === 'heads' ? ', but your opponent had no cards to discard' : ''}.`)
        state.lastAction = { id: randomUUID(), side: 'player', kind: 'ability', frontId: sourceId, abilityName: ability.name, abilityIndex, abilityEffect: 'draw' }
        await saveState(state)
