        if (!side.front.some((card) => card.instanceId === sourceId) || source.abilityUses?.[`${abilityIndex}:${ability.name}`] === state.turnNumber) return { success: false, error: 'Lazy Blow requires an Active Slaking that has not used this Power this turn.' }
        applyTcgBattleSlakingLazyBlow(state, 'player', source, abilityIndex, ability.name)
