export async function tcgBattleCharge(
  expectedRevision?: number,
): Promise<TcgBattleActionResult> {
  try {
    const user = await getUser()
    if (!user) return { success: false, error: 'Not authenticated' }

    const encounter = await getActiveTcgBattleEncounter(user.id)
    if (isTcgPvpEncounter(encounter)) {
      return runTcgPvpMutation(
        user.id,
        expectedRevision,
        (state, viewerSide) => {
          if (state.phase !== 'battle' || state.activeSide !== viewerSide) {
            return 'It is not your turn.'
          }
          clearDamageEvents(state)
          const side = state[viewerSide]
          const formatConfig = TCG_BATTLE_FORMATS[state.format]
          const energyChargeBlocked = state.energyChargeBlocked?.side === viewerSide && state.energyChargeBlocked.turnNumber === state.turnNumber
          const atCap = side.energy >= formatConfig.energyCap
          if (energyChargeBlocked) {
            state.log.unshift(`${getTcgPvpSideName(state, viewerSide)} could not charge Energy this turn.`)
          } else if (atCap) {
            state.log.unshift(
              `${getTcgPvpSideName(state, viewerSide)} ended the turn.`,
            )
          } else {
            const before = side.energy
            markTcgBattleEnergyChargeBonusUsed(state, viewerSide)
            side.energy = Math.min(
              formatConfig.energyCap,
              side.energy + formatConfig.chargeGain + getTcgBattleEnergyChargeBonus(state, viewerSide),
            )
            applyTcgBattleOpponentEnergyAttachmentDamage(state, viewerSide, side.energy - before)
            applyTcgBattleDarkraiEnergyZoneDamage(state, viewerSide, side.energy - before)
            applyTcgBattleEnergyAttachmentAbilities(state, viewerSide, side.energy - before, true)
            applyTcgBattleRadiantCharjabugEnergyAttachmentDamage(state, viewerSide, side.energy - before)
            applyTcgBattleEnergyZoneAsleepAbility(state, viewerSide, side.energy - before)
            state.log.unshift(
              `${getTcgPvpSideName(state, viewerSide)} charged ${side.energy - before} energy.`,
            )
          }
          state.consecutivePasses += 1
          state.lastAction = {
            id: randomUUID(),
            side: viewerSide,
            kind: 'charge',
          }
          settleTcgPvpAction(state, viewerSide)
        },
      )
    }

    return await withTcgBattleLock(user.id, async () => {
      const state = await loadState(user.id)
      await getActiveTcgBattleEncounter(user.id, state.encounterId)
      if (state.phase !== 'battle' || state.activeSide !== 'player') {
        return { success: false, error: 'It is not your turn.' }
      }

      clearDamageEvents(state)
      const formatConfig = TCG_BATTLE_FORMATS[state.format]
      const energyChargeBlocked = state.energyChargeBlocked?.side === 'player' && state.energyChargeBlocked.turnNumber === state.turnNumber
      const atCap = state.player.energy >= formatConfig.energyCap
      if (energyChargeBlocked) {
        state.log.unshift('You could not charge Energy this turn.')
      } else if (atCap) {
        state.log.unshift('You ended turn.')
      } else {
        const before = state.player.energy
        markTcgBattleEnergyChargeBonusUsed(state, 'player')
        state.player.energy = Math.min(
          formatConfig.energyCap,
          state.player.energy + formatConfig.chargeGain + getTcgBattleEnergyChargeBonus(state, 'player'),
        )
        applyTcgBattleOpponentEnergyAttachmentDamage(state, 'player', state.player.energy - before)
        applyTcgBattleDarkraiEnergyZoneDamage(state, 'player', state.player.energy - before)
        applyTcgBattleEnergyAttachmentAbilities(state, 'player', state.player.energy - before, true)
        applyTcgBattleRadiantCharjabugEnergyAttachmentDamage(state, 'player', state.player.energy - before)
        applyTcgBattleEnergyZoneAsleepAbility(state, 'player', state.player.energy - before)
        state.log.unshift(`You charged ${state.player.energy - before} energy.`)
      }
      state.consecutivePasses += 1
      afterPlayerAction(state)
      finishByStallIfNeeded(state)
      await saveState(state)
      return { success: true, state }
    })
  } catch (error) {
    return {
      success: false,
      error: error instanceof Error ? error.message : 'Unable to charge.',
    }
  }
}

